COLLDATA("sh10757","ar",[[6884,"«من شهر سيفه ثم وضعه فدمه هدر» .\n(صحيح) [ن ك] عن ابن الزبير. الصحيحة ٢٣٤٥: حل."],[6885,"«من صام الأبد فلا صام ولا أفطر» .\n(صحيح) [حم ن هـ ك] عن عبد الله بن الشخير. صحيح الترغيب ٢/٨٨: حب. ن، طب - ابن عمر. ن، حب - عمران. ن - أبي قتادة."],[6886,"«من صام ثلاثة أيام من كل شهر فقد صام الدهر كله» .\n(صحيح) [حم ت ن هـ الضياء] عن أبي ذر. صحيح الترغيب ١٠٢٥، الإرواء ٩٤٧."],[6887,"«من صام رمضان إيمانا واحتسابا غفر له ما تقدم من ذنبه [وما تأخر]» ١ ... [خط] عن ابن عباس."],[6888,"(١) ما بين الحاصرتين زيادة شاذة. وانظر الحديث الآتي ٦٣٢٦."],[6889,"«من صام رمضان إيمانا واحتسابا غفر له ما تقدم من ذنبه» .\n(صحيح) [حم ق ٤] عن أبي هريرة."],[6890,"«من صام رمضان وأتبعه ستا من شوال كان كصوم الدهر» ... [حم م ٤] عن أبي أيوب.\n(صحيح) الإرواء ٩٥٠، الروض النضير ٩١١، مختصر مسلم ٦١٨."],[6891,"٢١٣٥ - «من صام ستة أيام بعد الفطر كان تمام السنة ﴿مَنْ جَاءَ بِالْحَسَنَةِ فَلَهُ عَشْرُ أَمْثَالِهَا﴾» .\n(صحيح) [هـ] عن ثوبان. صحيح الترغيب ٩٩٧: ن، ابن خزيمة، حب."],[6892,"٢١٣٦ - «من صام يوما في سبيل الله باعد الله بذلك اليوم حر جهنم عن وجهه سبعين خريفا» .\n(صحيح) [ن هـ] عن أبي سعيد. م ٣/١٥٩."],[6893,"٢١٣٧ - «من صام يوما في سبيل الله باعد الله منه جهنم مسيرة مائة عام» .\n(حسن) [ن] عن عقبة بن عامر."],[6894,"٢١٣٨ - «من صام يوما في سبيل الله باعد الله وجهه من جهنم سبعين عاما» .\n(صحيح) [ن] عن أبي سعيد. م ٣/١٥٩."],[6895,"«من صام يوما في سبيل الله بعد الله وجهه عن النار سبعين خريفا» .\n(صحيح) [حم ق ت ن] عن أبي سعيد. صحيح الترغيب ٩٧٨."],[6896,"٢١٣٩ - «من صام يوما في سبيل الله جعل الله بينه وبين النار خندقا كما بين السماء والأرض» ... [ت] عن أبي أمامة.\n(صحيح) المشكاة ٢٠٦٤، الصحيحة ٥٦٣، صحيح الترغيب ٩٨١."],[6897,"٢١٤٠ - «من صام يوما في سبيل الله زحزح الله وجهه عن النار بذلك اليوم سبعين خريفا» ... [حم ت ن هـ] عن أبي هريرة.\n(صحيح) صحيح الترغيب ٩٨٠."],[6898,"«من صام يوم عرفة غفر الله له سنتين: سنة أمامه وسنة خلفه» ... [هـ] عن قتادة بن النعمان.\n(صحيح) الأحاديث الضعيفة ٤١٢: صحيح الترغيب ١٠٠١: م - أبي قتادة١."],[6899,"«من صرع عن دابته فهو شهيد» ... [طب] عن عقبة بن عامر.\n(صحيح) الصحيحة ٢٣٤٦: الروياني؛ د، ك، هق - أبي مالك الأشعري."],[6900,"«من صلى البردين دخل الجنة» .\n(صحيح) [م] عن أبي موسى. مختصر مسلم ٢٠٩."],[6901,"«من صلى الصبح فهو في ذمة الله فلا يتبعنكم الله بشيء من ذمته» .\n(صحيح) [ت] عن أبي هريرة. يشهد له ما بعده."],[6902,"٢١٤١ - «من صلى الصبح فهو في ذمة الله فلا يطلبنكم الله من ذمته بشيء فإن من يطلبه من ذمته بشيء يدركه ثم يكبه على وجهه في نار جهنم» ... [حم م ت] عن جندب البجلي.\n(صحيح) صحيح الترغيب ٣٦٣، ٤٥٩: طب."],[6903,"\"من صلى الضحى أربعا وقبل الأولى أربعا بني له بيت في الجنة\".\n(حسن) [طس] عن أبي موسى. الصحيحة ٢٣٤٩."],[6904,"(١) قلت: تقدم حديثه بلفظ: [صوم يوم عرفة ... ...] رقم ٣٨٠٦."],[6905,"«من صلى العشاء في جماعة فكأنما قام نصف ليلة ومن صلى الصبح في جماعة فكأنما صلى الليل كله» .\n(صحيح) [حم م] عن عثمان. مختصر مسلم ٣٢٤، الروض النضير ٦٦٣."],[6906,"٢١٤٢ - «من صلى العشاء في جماعة كان كقيام نصف ليلة ومن صلى العشاء والفجر في جماعة كان كقيام ليلة» .\n(صحيح) [د ت] عن عثمان. صحيح أبي داود ٥٦٤."],[6907,"«من صلى الغداة كان في ذمة الله حتى يمسي» .\n(صحيح) [طب] عن ابن عمر. يشهد له الحديثان اللذان بعده والحديثان ٦٣٣٨، ٦٣٣٩."],[6908,"٢١٤٣ - «من صلى الفجر فهو في ذمة الله فلا يطلبنكم الله بشيء من ذمته» .\n(صحيح) [هـ] عن سمرة. صحيح الترغيب ٤١٨."],[6909,"«من صلى الفجر فهو في ذمة الله وحسابه على الله» .\n(حسن) [طب] عن والد أبي مالك الأشجعي. صحيح الترغيب ٤٥٨."],[6910,"٢١٤٤ - «من صلى الفجر في جماعة ثم قعد يذكر الله حتى تطلع الشمس ثم صلى ركعتين كانت له كأجر حجة وعمرة تامة تامة تامة» .\n(صحيح) [ت] عن أنس. صحيح الترغيب ٤٦٤."],[6911,"«من صلى ركعة من الصبح ثم طلعت الشمس فليصل الصبح» .\n(صحيح) [ك] عن أبي هريرة. الإرواء ٢٥٣."],[6912,"«من صلى صلاة لم يتمها زيد عليها من سبحاته حتى تتم» .\n(صحيح) [طب] عن عائذ بن قرط. الصحيحة ٢٣٥٠: ابن مندة، ابن شاهين، ابن أبي خيثمة، الضياء."],[6913,"٢١٤٥ - «من صلى صلاة لم يقرأ فيها بأم القرآن فهي خداج فهي خداج فهي خداج غير تمام» ... [حم م ٤] عن أبي هريرة.\n(صحيح) صحيح أبي داود ٧٧٩."],[6914,"٢١٤٦ - «من صلى صلاتنا واستقبل قبلتنا وأكل ذبيحتنا فذاكم المسلم الذي له ذمة الله وذمة رسوله فلا تخفروا الله في ذمته» .\n(صحيح) [خ ن] عن أنس."],[6915,"٢١٤٧ - «من صلى صلاتنا ونسك نسكنا فقد أصاب النسك ومن نسك قبل الصلاة فلا نسك له» .\n(صحيح) [ق د] عن البراء."],[6916,"٢١٤٨ - «من صلى على جنازة فله قيراط فإن شهد دفنها فله قيراطان القيراط مثل أحد» ... [م هـ] عن ثوبان.\n(صحيح) أحكام الجنائز ص ١٦٨: الطيالسي، حم."],[6917,"٢١٤٩ - «من صلى على جنازة فله قيراط ومن انتظرها حتى توضع في اللحد فله قيراطان والقيراطان مثل الجبلين العظيمين» .\n(صحيح) [حم ن هـ] عن أبي هريرة."],[6918,"٢١٥٠ - «من صلى على جنازة في المسجد فليس له شيء» .\n(صحيح) [حم هـ] عن أبي هريرة. الصحيحة ٢٣٥١."],[6919,"٢١٥١ - «من صلى على جنازة ولم يتبعها فله قيراط فإن تبعها فله قيراطان» .\n(صحيح) [م ت] عن أبي هريرة. أحكام الجنائز."],[6920,"«من صلى عليه مائة من المسلمين غفر له» .\n(صحيح) [هـ] عن أبي هريرة. أحكام الجنائز ص ٩٩."],[6921,"«من صلى على حين يصبح عشرا وحين يمسي عشرا أدركته شفاعتي يوم القيامة» .\n(حسن) [طب] عن أبي الدرداء. الترغيب ٢٣٢."],[6922,"«من صلى علي واحدة صلى الله عليه بها عشرا» .\n(صحيح) [حم م ٣] عن أبي هريرة. الضعيفة ٢١٥."],[6923,"«من صلى علي واحدة صلى الله عليه عشر صلوات وحط عنه عشر خطيئات ورفع له عشر درجات» .\n(صحيح) [حم خد ن ك] عن أنس. المشكاة ٩٢٢، الترغيب ٢/٢٧٧: حب."],[6924,"«من صلى في اليوم والليلة اثنتي عشرة ركعة تطوعا بنى الله له بيتا في الجنة» .\n(صحيح) [حم م د ن هـ] عن أم حبيبة. المشكاة ١١٥٩: صحيح أبي داود ١١٣٦."],[6925,"٢١٥٢ - «من صلى في ثوب فليخالف بين طرفيه» .\n(صحيح) [خ] عن أبي هريرة."],[6926,"٢١٥٣ - «من صلى في يوم وليلة ثنتي عشرة ركعة بني له بيت في الجنة: أربعا قبل الظهر وركعتين بعدها وركعتين بعد المغرب وركعتين بعد العشاء وركعتين قبل صلاة الغداة» .\n(صحيح) [ت] عن أم حبيبة. صحيح الترغيب ٥٧٨."],[6927,"٢١٥٤ - «من صلى قائما فهو أفضل ومن صلى قاعدا فله نصف أجر القائم ومن صلى نائما فله نصف أجر القاعد» .\n(صحيح) [خ ت ن هـ] عن عمران بن حصين. الإرواء ٢٩٩، ٤٥٥."],[6928,"٢١٥٥ - \"من صلى قبل الظهر أربعا وبعدها أربعا، حرمه الله على النار\".\n(صحيح) [حم ت ن هـ] عن أم حبيبة. صحيح الترغيب ٥٨٣، ابن خزيمة."],[6929,"٢١٥٦ - «من صلى لله أربعين يوما في جماعة يدرك التكبيرة الأولى كتب له براءتان: براءة من النار وبراءة من النفاق» .\n(حسن) [ت] عن أنس. الضعيفة ٣٦٤، الترغيب ٤٠٧."],[6930,"٢١٥٧ - «من صلى وجلس ينتظر الصلاة لم يزل في صلاة حتى تأتيه الصلاة التي يلاقيها» .\n(صحيح) [ن] عن عبد الله بن سلام وأبي هريرة. المشكاة ١٣٥٩: مالك، د، ت، ن."],[6931,"«من صمت نجا» .\n(صحيح) [حم ت] عن ابن عمرو. الصحيحة ٥٣٦."],[6932,"«من صنع إليه معروف فقال لفاعله: جزاك الله خيرا فقد أبلغ في الثناء» ... [ت ن حب] عن أسامة بن زيد.\n(صحيح) المشكاة ٣٠٢٤، صحيح الترغيب ٩٥٩."],[6933,"٢١٥٨ - «من صنع أمرا على غير أمرنا فهو رد» .\n(صحيح) [د] عن عائشة. غاية المرام ٥."],[6934,"٢١٥٩ - «من صور صورة عذبه الله بها يوم القيامة حتى ينفخ فيها وليس بنافخ ومن تحلم كلف أن يعقد شعيرتين وليس بعاقد ومن استمع إلى حديث قوم يفرون منه صب في أذنيه الآنك يوم القيامة» .\n(صحيح) [حم د ت] عن ابن عباس. غاية المرام ١٢٠و ١٦٥."],[6935,"«من صور صورة في الدنيا كلف أن ينفخ فيها الروح يوم القيامة وليس بنافخ» .\n(صحيح) [حم ق ت] عن ابن عباس. غاية المرم ١٢٠و ١٦٥."],[6936,"«من ضار ضار الله به ومن شاق شاق الله عليه» .\n(حسن) [حم ٤] عن أبي صرمة. الإرواء ٨٩٦."],[6937,"«من ضحى قبل الصلاة فإنما ذبح لنفسه ومن ذبح بعد الصلاة فقد تم نسكه وأصاب سنة المسلمين» .\n(صحيح) [ق] عن البراء. الإرواء ١١٥٤."],[6938,"«من ضرب بسوط ظلما اقتص منه يوم القيامة» .\n(صحيح) [خد هق] عن أبي هريرة. الصحيحة ٢٣٥٢: طص."],[6939,"«من ضرب غلاما له حدا لم يأته أو لطمه فإن كفارته أن يعتقه» .\n(صحيح) [م] عن ابن عمر. مختصر مسلم ٩٠١."],[6940,"«من ضرب مملوكه ظالما أقيد منه يوم القيامة» .\n(صحيح) [طب] عن عمار. الصحيحة ٢٣٥٣: حل."],[6941,"«من ضن بالمال أن ينفقه وبالليل أن يكابده فعليه بسبحان الله وبحمده» ... [أبونعيم في المعرفة] عن عبد الله بن خبيب.\n(صحيح) الترغيب ٢/٢٤٣، ٢٥٠: خد، طب - ابن مسعود. طب - أبي أمامة."],[6942,"«من ضيق منزلا أو قطع طريقا أو آذى مؤمنا فلا جهاد له» .\n(صحيح) [حم د] عن معاذ بن أنس. المشكاة ٣٩٢٠."],[6943,"«من طاف بالبيت سبعا وصلى ركعتين كان كعتق رقبة» .\n(صحيح) [هـ] عن ابن عمر. الترغيب ٢/١٢٢."],[6944,"\"من طاف بهذا البيت أسبوعا فأحصاه كان كعتق رقبة لا يضع قدما ولا يرفع أخرى إلا حط الله عنه بها خطيئة وكتب له بها\nحسنة [...] ت ن ك\" عن ابن عمر. (صحيح) المشكاة ٢٥٨٠، الترغيب ٢/١٢٢، ابن خزيمة، حب."],[6945,"«من طلب الشهادة صادقا أعطيها ولو لم تصبه» .\n(صحيح) [حم م] عن أنس."],[6946,"٢١٦٠ - «من طلب العلم ليباهي به العلماء أو ليماري به السفهاء أو ليصرف به وجوه الناس إليه فهو في النار» .\n(حسن) [هـ] عن ابن عمر. صحيح الترغيب ١٠٤، المشكاة ٢٢٥."],[6947,"«من طلب العلم ليجاري به العلماء أو ليماري به السفهاء أو يصرف به وجوه الناس إليه أدخله الله في النار» .\n(حسن) [ت] عن كعب بن مالك. المشكاة ٢٢٥."],[6948,"٢١٦١ - «من طلب حقا فليطلبه في عفاف واف أو غير واف» .\n(صحيح) [هـ حب ك] عن ابن عمر وعائشة. الترغيب ٣/٢٠."],[6949,"«من ظلم قيد شبر من الأرض طوقه من سبع أرضين» .\n(صحيح) [حم ق] عن عائشة وسعيد بن زيد."],[6950,"٢١٦٢ - «من عادى عمارا عاداه الله ومن أبغض عمارا أبغضه الله» .\n(صحيح) [حم ن حب ك] عن خالد بن الوليد. المشكاة ٦٢٤٧."],[6951,"٢١٦٣ - «من عاد مريضا أو زار أخا له في الله ناداه مناد: أن طبت وطاب ممشاك وتبوأت من الجنة منزلا» .\n(حسن) [ت هـ] عن أبي هريرة. المشكاة ٥٠٥١."],[6952,"٢١٦٤ - «من عاد مريضا لم يحضر أجله فقال عنده سبع مرات: أسأل الله العظيم رب العرش العظيم أن يشفيك إلا عافاه الله من ذلك المرض» .\n(صحيح) [د ك] عن ابن عباس. الكلم الطيب ١٥٠، المشكاة ١٥٥٣."],[6953,"«من عاد مريضا لم يزل في خرفة الجنة حتى يرجع» .\n(صحيح) [م] عن ثوبان."],[6954,"«من عاذ بالله فقد عاذ بمعاذ» .\n(صحيح) [حم] عن عثمان وابن عمر. الترغيب ٣/١٣١ - ١٣٢: حب - ابن سعد."],[6955,"«من عال جاريتين حتى يدركا دخلت أنا وهو الجنة كهاتين» .\n(صحيح) [م ت] عن أنس. الصحيحة ٢٩٧و ١١٢٠: ك."],[6956,"«من عرض عليه ريحان فلا يرده فإنه خفيف المحمل طيب الريح» .\n(صحيح) [م د] عن أبي هريرة. المشكاة ٣٠١٦."],[6957,"٢١٦٥ - «من عرض عليه طيب فلا يرده فإنه خفيف المحمل طيب الرائحة» .\n(صحيح) [حم ن] عن أبي هريرة. المصدر نفسه."],[6958,"«من علق تميمة فقد أشرك» .\n(صحيح) [حم ك] عن عقبة بن عامر. الصحيحة ٤٩٢."],[6959,"«من علم الرمي ثم تركه فليس منا» .\n(صحيح) [م] عن عقبة بن عامر. مختصر مسلم ١١٠٤."],[6960,"\"من علم علما فله أجر من عمل به لا ينقص من أجر العامل\".\n(صحيح) [هـ] عن معاذ بن أنس. صحيح الترغيب ٧٧."],[6961,"«من عمر من أمتي سبعين سنة فقد أعذر الله إليه في العمر» .\n(صحيح) [ك] عن سهل بن سعد. الصحيحة ١٠٨٨."],[6962,"«من عمل عملا ليس عليه أمرنا فهو رد» .\n(صحيح) [حم م] عن عائشة. مختصر مسلم ١٢٣٧، غاية المرام ٥، الإرواء ٢٧٦."],[6963,"«من غدا إلى المسجد وراح أعد الله له نزلا من الجنة كلما غدا وراح» .\n(صحيح) [حم ق] عن أبي هريرة. المشكاة ٦٩٨."],[6964,"«من غرس غرسا لم يأكل منه آدمي ولا خلق من خلق الله إلا كان له صدقة» .\n(صحيح) [حم] عن أبي الدرداء. الترغيب ٣/٢٤٥."],[6965,"«من غزا في سبيل الله ولم ينو إلا عقالا فله ما نوى» .\n(صحيح) [حم ن ك] عن عبادة بن الصامت. المشكاة ٣٨٥٠."],[6966,"«من غسل الميت فليغتسل ومن حمله فليتوضأ» .\n(صحيح) [د هـ حب] عن أبي هريرة. المشكاة ٥٤١، أحكام الجنائز ص ٥٣، الإرواء ١٤٤."],[6967,"«من غسل ميتا فستره ستره الله من الذنوب ومن كفنه كساه الله من السندس» .\n(حسن) [طب] عن أبي أمامة. الصحيحة ٢٣٥٣: ابن بشران."],[6968,"«من غسل ميتا فليغتسل» .\n(صحيح) [حم] عن المغيرة. الإرواء ١٤٤."],[6969,"٢١٦٦ - «من غسل يوم الجمعة واغتسل ثم بكر وابتكر ومشى ولم يركب ودنا من الإمام واستمع وأنصت ولم يلغ كان له بكل خطوة يخطوها من بيته إلى المسجد عمل سنة أجر صيامها وقيامها» ... [حم ٤ حب ك] عن أوس بن أوس.\n(صحيح) صحيح أبي داود ٣٧٢، صحيح الترغيب ٦٩٠."],[6970,"«من غش فليس منا» ... [ت] عن أبي هريرة.\n(صحيح) مختصر مسلم ١٢٣٥، الإرواء ١٣١٩، أحاديث البيوع."],[6971,"٢١٦٧ - «من غشنا فليس منا» .\n(صحيح) [هـ] عن أبي الحمراء. الإرواء ١٣١٩، أحاديث البيوع: م."],[6972,"«من غشنا فليس منا والمكر والخداع في النار» .\n(صحيح) [طب حل] عن ابن مسعود. الإرواء ١٣١٩، الصحيحة ١٠٥٨: حب، طس."],[6973,"«من غل بعيرا أو شاة أتى يحمله يوم القيامة» .\n(صحيح) [حم الضياء] عن عبد الله بن أنيس. الصحيحة ٢٣٥٤: هـ."],[6974,"٢١٦٨ - «من فارق الجماعة شبرا فقد خلع ربقة الإسلام من عنقه» .\n(صحيح) [حم د ك] عن أبي ذر. المشكاة ١٨٥، السنة ٧٩٢: ابن أبي عاصم - أبي ذر، حم، ك - الحارث الأشعري."],[6975,"٢١٦٩ - «من فارق الروح جسده وهو بريء من ثلاث دخل الجنة: الكبر والدين والغلول» .\n(صحيح) [حم ت ن هـ حب ك] عن ثوبان. المشكاة ٢٩٢١، الترغيب ٣/٣٢."],[6976,"«من فرق بين والدة وولدها فرق الله بينه وبين أحبته يوم القيامة» .\n(صحيح) [حم ت ك] عن أبي أيوب. المشكاة ٣٣٦١."],[6977,"٢١٧٠ - «من فصل في سبيل الله فمات أو قتل أو وقصته فرسه أو بعيره أو لدغته هامة أو مات على فراشه بأي حتف شاء الله فإنه شهيد وإن له الجنة» .\n(حسن) [د ك] عن أبي مالك الأشعري. أحكام الجنائز ص ٣٧."],[6978,"«من فطر صائما أو جهز غازيا فله مثل أجره» .\n(صحيح) [هق] عن زيد بن خالد. صحيح الترغيب ١٠٧٢، المشكاة ١٩٩٢."],[6979,"«من فطر صائما كان له مثل أجره غير أنه لا ينقص من أجر الصائم شيئا» ... [حم ت هـ حب] عن زيد بن خالد.\n(صحيح) صحيح الترغيب ١٠٧٢، ابن خزيمة."],[6980,"٢١٧١ - «من قاتل في سبيل الله فواق ناقة فقد وجبت له الجنة ومن سأل الله القتل في سبيل الله من نفسه صادقا ثم مات أو قتل فإنه له أجر شهيد ومن جرح جرحا في سبيل الله أو نكب نكبة فإنها تجيء يوم القيامة كأغزر ما كانت لونها لون الزعفران وريحها ريح المسك ومن خرج به خراج في سبيل الله كان عليه طابع الشهداء» .\n(صحيح) [حم ٣ حب] عن معاذ. المشكاة ٣٨٢٥، الترغيب ٢/١٦٩."],[6981,"«من قاتل لتكون كلمة الله هي العليا فهو في سبيل الله» .\n(صحيح) [حم ق ٤] عن أبي موسى. مختصر مسلم ١٠٨٨، المشكاة ٣٨١٤."],[6982,"٢١٧٢ - \"من قال إذا أصبح: لا إله إلا الله وحده لا شريك له له الملك وله الحمد وهو على كل شيء قدير كان له عدل رقبة من ولد إسماعيل وكتبت له بها عشر حسنات وحط عنه بها عشر سيئات ورفع له بها عشر درجات وكان في حرز من الشيطان حتى يمسي وإذا قالها إذا أمسى كان له مثل ذلك حتى يصبح\".\n(صحيح) [حم د هـ] عن أبي عياش الزرقي."],[6983,"٢١٧٣ - «من قال إذا خرج من بيته: بسم الله توكلت على الله لا حول ولا قوة إلا بالله يقال له: كفيت ووقيت وتنحى عنه الشيطان» ... [ت] عن أنس.\n(صحيح) الترغيب ٢/٢٦٤، المشكاة ٢٤٤٣: د، حب، ابن السني."],[6984,"٢١٧٤ - «من قال أنا خير من يونس بن متى فقد كذب» .\n(صحيح) [خ ت هـ] عن أبي هريرة."],[6985,"٢١٧٥ - «من قال إني بريء من الإسلام فإن كان كاذبا فهو كما قال وإن كان صادقا لم يعد إلى الإسلام سالما» .\n(صحيح) [ن هـ ك] عن بريدة. الإرواء ٢٥٧٦."],[6986,"٢١٧٦ - «من قال حين يسمع المؤذن: وأنا أشهد أن لا إله إلا الله وحده لا شريك له وأشهد أن محمدا عبده ورسوله رضيت بالله ربا وبمحمد رسولا وبالإسلام دينا غفر الله له ما تقدم من ذنبه» .\n(صحيح) [حم م ٤] عن سعد. مختصر مسلم ٢٠٠، صحيح أبي داود ٥٣٦."],[6987,"٢١٧٧ - «من قال حين يسمع النداء: اللهم رب هذه الدعوة التامة والصلاة القائمة آت محمدا الوسيلة والفضيلة وابعثه مقاما محمودا الذي وعدته حلت له شفاعتي يوم القيامة» .\n(صحيح) [حم خ ٤] عن جابر. صحيح أبي داود ٥٤٠، فقه السيرة ٤١٨، الإرواء ٢٤٣، السنة ٨٢٦: ابن أبي عاصم."],[6988,"٢١٧٨ - «من قال حين يصبح أو حين يمسي: اللهم أنت ربي لا إله إلا أنت خلقتني وأنا عبدك وأنا على عهدك ووعدك ما استطعت أعوذ بك من شر ما صنعت أبوء لك بنعمتك علي وأبوء بذنبي فاغفر لي فإنه لا يغفر الذنوب إلا أنت فمات من يومه أو ليلته دخل الجنة» .\n(صحيح) [حم د ن هـ حب ك] عن بريدة. الصحيحة ١٧٤٧."],[6989,"٢١٧٩ - «من قال حين يصبح وحين يمسي: سبحان الله العظيم وبحمده مائة مرة لم يأت أحد يوم القيامة بأفضل مما جاء به إلا أحد قال مثل ذلك وزاد عليه» ... [حم م د ت] عن أبي هريرة.\n(صحيح) مختصر مسلم ١٩٠٣، صحيح الترغيب ٦٥٠."],[6990,"٢١٨٠ - «من قال حين يمسي: بسم الله الذي لا يضر مع اسمه شيء في الأرض ولا في السماء وهو السميع العليم ثلاث مرات لم يصبه فجأة بلاء حتى يصبح ومن قالها حين يصبح ثلاث مرات لم يصبه فجأة بلاء حتى يمسي» .\n(صحيح) [د حب ك] عن عثمان. صحيح الترغيب ٦٥٢."],[6991,"٢١٨١ - «من قال حين يمسي ثلاث مرات: أعوذ بكلمات الله التامات من شر ما خلق لم يضره لدغة حية في تلك الليلة» .\n(صحيح) [ت حب ك] عن أبي هريرة. صحيح الترغيب ٧٤٩."],[6992,"٢١٨٢ - «من قال رضيت بالله ربا وبالإسلام دينا وبمحمد نبيا وجبت له الجنة» .\n(صحيح) [د حب ك] عن أبي سعيد. الصحيحة ٣٣٤."],[6993,"«من قال: سبحان الله العظيم وبحمده غرست له بها نخلة في الجنة» .\n(صحيح) [ت حب ك] عن جابر. الروض النضير ٢٤٣، الصحيحة ٦٤."],[6994,"٢١٨٣ - «من قال: سبحان الله وبحمده سبحانك اللهم وبحمدك أشهد أن لا إله إلا أنت أستغفرك وأتوب إليك فإن قالها في مجلس ذكر كانت كالطابع يطبع عليه ومن قالها في مجلس لغوكانت كفارة له» .\n(صحيح) [ن ك] عن جبير بن مطعم. الصحيحة ٨١."],[6995,"«من قال: سبحان الله وبحمده في يوم مائة مرة حطت خطاياه وإن كانت مثل زبد البحر» .\n(صحيح) [حم ق ت هـ] عن أبي هريرة. مختصر مسلم ١٩٠٨."],[6996,"٢١٨٤ - «من قال لصاحبه يوم الجمعة والإمام يخطب: أنصت فقد لغا» ... [ت ن] عن أبي هريرة.\n(صحيح) صحيح أبي داود ١٠١٨، الإرواء ٦١٩: حم، ق١."],[6997,"«من قال: لا إله إلا الله مخلصا دخل الجنة» .\n(صحيح) [البزار] عن أبي سعيد. الصحيحة ٢٣٥٥: حم، حب، حل - جابر. حل - أنس."],[6998,"«من قال: لا إله إلا الله نفعته يوما من دهره يصيبه قبل ذلك ما أصابه» .\n(صحيح) [البزار هب] عن أبي هريرة. الروض النضير ١١٤٥، الترغيب ٢/٢٣٨، الصحيحة ١٩٣٢: ابن الأعرابي، طص، حل، الخطيب."],[6999,"٢١٨٥ - \"من قال: لا إله إلا الله وحده لا شريك له له الملك وله الحمد وهو على كل شيء قدير عشرا كان كمن أعتق رقبة من ولد إسماعيل\".\n(صحيح) [ق ت ن] عن أبي أيوب ولفظ [ت]:١ كانت له عدل أربع رقاب من ولد إسماعيل\"."],[7000,"(١) قلت: وقد مضى لفظهم برقم ٧٣٧."],[7001,"٢١٨٦ - «من قال: لا إله إلا الله وحده لا شريك له له الملك وله الحمد،.... وهو على كل شيء قدير عشر مرات كان له بعدل نسمة» .\n(صحيح) [حم ن حب ك] عن البراء. الترغيب ٢/٢٤١."],[7002,"٢١٨٧ - «من قال: لا إله إلا الله وحده لا شريك له له الملك وله الحمد وهو على كل شيء قدير في يوم مائة مرة كانت له عدل عشر رقاب وكتبت له مائة حسنة ومحيت عنه مائة سيئة وكانت له حرزا من الشيطان يومه ذلك حتى يمسي ولم يأت أحد بأفضل مما جاء به إلا أحد عمل عملا أكثر من ذلك» .\n(صحيح) [حم ق ت هـ] عن أبي هريرة. مختصر مسلم ١٩٠٨."],[7003,"٢١٨٨ - «من قال: لا إله إلا الله وكفر بما يعبد من دون الله حرم ماله ودمه وحسابه على الله عز وجل» .\n(صحيح) [حم م] عن والد أبي مالك الأشجعي."],[7004,"٢١٨٩ - «من قام بعشر آيات لم يكتب من الغافلين ومن قام بمائة آية كتب من القانتين ومن قام بألف آية كتب من المقنطرين» .\n(صحيح) [د حب] عن ابن عمرو. الصحيحة ٦٤٢."],[7005,"«من قام رمضان إيمانا واحتسابا غفر له ما تقدم من ذنبه» .\n(صحيح) [ق ٤] عن أبي هريرة. مختصر مسلم ٣٩٨، الإرواء ٩٠٦."],[7006,"(١) قلت: بل هي رواية مسلم أيضا ٨/٦٩، وهي المحفوظة، وأما الرواية الأولى: [رقبة] فهي شاذة كما بينه الحافظ في [الفتح] ."],[7007,"«من قام ليلة القدر إيمانا واحتسابا غفر له ما تقدم من ذنبه» .\n(صحيح) [خ ٣] عن أبي هريرة."],[7008,"«من قتل تحت راية عمية ينصر العصبية ويغضب للعصبية فقتلته جاهلية» .\n(صحيح) [م ن] عن جندب [هـ] عن أبي هريرة. الصحيحة ٤٢٤."],[7009,"٢١٩٠ - «من قتل خطأ فديته مائة من الإبل ثلاثون بنت مخاض وثلاثون بنت لبون وثلاثون حقة وعشرة بني لبون» .\n(حسن) [حم ن] عن ابن عمرو. الإرواء ٢١٩٩."],[7010,"«من قتل دون ماله فهو شهيد» .\n(صحيح) [حم ق ت ن] عن ابن عمرو [ت حب] عن سعيد بن زيد [ن] عن بريدة. الإرواء ٧٠٨، أحكام الجنائز ص ٤١."],[7011,"«من قتل دون ماله فهو شهيد ومن قتل دون دمه فهو شهيد ومن قتل دون دينه فهو شهيد ومن قتل دون أهله فهو شهيد» .\n(صحيح) [حم ٣ حب] عن سعيد بن زيد. المشكاة ٣٥٢٩، أحكام الجنائز ٤٢، الترغيب ٢/٢٠٤، الإرواء ٧٠٨."],[7012,"٢١٩١ - «من قتل دون ماله مظلوما فله الجنة» .\n(صحيح) [ن] عن ابن عمرو. أحكام الجنائز ص ٤١."],[7013,"«من قتل دون مظلمته فهو شهيد» .\n(صحيح) [ن الضياء] عن سويد بن مقرن. أحكام الجنائز ٤٢: حم - أبن عباس."],[7014,"٢١٩٢ - «من قتل رجلا من أهل الذمة لم يجد ريح الجنة وإن ريحها ليوجد من مسيرة سبعين عاما» .\n(صحيح) [حم ن] عن رجل. الترغيب ٣/٢٠٤: هـ، ك - أبي هريرة."],[7015,"٢١٩٣ - «من قتل في سبيل الله فهو شهيد ومن مات في سبيل الله فهو شهيد ومن مات في الطاعون فهو شهيد ومن مات في البطن فهو شهيد ومن غرق فهو شهيد» .\n(صحيح) [م] عن أبي هريرة. أحكام الجنائز ٣٦ - ٣٧: حم."],[7016,"٢١٩٤ - «من قتل في عميا أو رميا يكون بينهم بحجر أو سوط فعقله عقل خطأ ومن قتل عمدا فقود يديه فمن حال بينه وبينه فعليه لعنة الله والملائكة والناس أجمعين» .\n(صحيح) [د ن هـ] عن ابن عباس١. المشكاة ٣٤٧٨."],[7017,"٢١٩٥ - «من قتل في عميا في رمى يكون بينهم بحجارة أو بالسياط أو ضرب بعصا فهو خطأ وعقله عقل الخطأ ومن قتل عمدا فهو قود يد ومن حال دونه فعليه لعنة الله وغضبه لا يقبل منه صرفا ولا عدلا» .\n(صحيح) [د ن] عن ابن عباس. المصدر نفسه."],[7018,"«من قتل كافر فله سلبه» .\n(صحيح) [ق د ت] عن قتادة [حم د] عن أنس [حم هـ] عن سمرة. الإرواء ١٢٢١."],[7019,"٢١٩٦ - «من قتل له قتيل فهو بخير النظرين إما أن يقاد وإما أن يفدي» .\n(صحيح) [ن هـ] عن أبي هريرة. الإرواء ١٠٥٧."],[7020,"«من قتل مؤمنا فاغتبط بقتله لم يقبل الله منه صرفا ولا عدلا» .\n(صحيح) [د الضياء] عن عبادة بن الصامت. الترغيب ٣/٢٠٤."],[7021,"(١) قلت: وهذا اللفظ لـ[ن]، والذي بعده لـ[د] ."],[7022,"٢١٩٧ - «من قتل متعمد دفع إلى أولياء المقتول فإن شاءوا قتلوا وإن شاءوا أخذوا الدية وهي ثلاثون حقة وثلاثون جذعة وأربعون خلفة وما صولحوا عليه فهو لهم» .\n(صحيح) [حم ت هـ] عن ابن عمرو. الإرواء ٢١٩٩."],[7023,"«من قتل معاهدا في غير كنهه حرم الله عليه الجنة» .\n(صحيح) [حم د ن ك] عن أبي بكرة. الترغيب ٣/٢٠٤: الدارمي."],[7024,"«من قتل معاهدا لم يرح رائحة الجنة وإن ريحها ليوجد من مسيرة أربعين عاما» .\n(صحيح) [حم خ ن هـ] عن ابن عمرو. غاية المرام ٤٤٩."],[7025,"٢١٩٨ - «من قتل نفسا معاهدة بغير حلها حرم الله عليه الجنة: أن يشم ريحها» .\n(صحيح) [حم ن] عن أبي بكرة. الترغيب ٣/٢٠٤: ابن خزيمة، حب، ك."],[7026,"٢١٩٩ - «من قتل نفسه بحديدة فحديدته في يده يتوجأ بها في بطنه في نار جهنم خالدا مخلدا فيها أبدا ومن شرب سما فقتل نفسه فهو يتحساه في نار جهنم خالدا مخلدا فيها أبدا ومن تردى من جبل فقتل نفسه فهو يتردى في نار جهنم خالدا مخلدا فيها أبدا» .\n(صحيح) [حم ق ت ن هـ] عن أبي هريرة. مختصر مسلم ١٠٢٦."],[7027,"٢٢٠٠ - «من قتل وزغة في أول ضربة كتب له مائة حسنة ومن قتلها في الضربة الثانية فله كذا وكذا حسنة وإن قتلها في الضربة الثالثة فله كذا وكذا حسنة» .\n(صحيح) [حم م د ت هـ] عن أبي هريرة. مختصر مسلم ١٥٠١، هق ٢/٢٦٧."],[7028,"«من قتله بطنه لم يعذب في قبره» .\n(صحيح) [حم ت ن حب] عن خالد بن عرفطة وسليمان بن صرد. الروض النضير ٢٩٨، أحكام الجنائز ٣٨، المشكاة ١٥٧٣، الترغيب ٢/٢٠٤."],[7029,"٢٢٠١ - «من قذف مملوكه بالزنا يقام عليه الحد يوم القيامة إلا أن يكون كما قال» .\n(صحيح) [م] عن أبي هريرة. مختصر مسلم ٩٠٣."],[7030,"«من قذف مملوكه وهو بريء مما قال جلد يوم القيامة حدا إلا أن يكون كما قال» .\n(صحيح) [حم ق د ت] عن أبي هريرة. الروض النضير ١١٤٦."],[7031,"«من قرأ آية الكرسي دبر كل صلاة مكتوبة لم يمنعه من دخول الجنة إلا أن يموت» .\n(صحيح) [ن حب] عن أبي أمامة. المشكاة ٩٧٤، الصحيحة ٩٧٢."],[7032,"«من قرأ الآيتين من آخر سورة البقرة في ليلة كفتاه» .\n(صحيح) [٤] عن ابن مسعود. مختصر مسلم ٢٠٩٧، صحيح أبي داود ١٢٦٣: حم، ق، الدارمي."],[7033,"«من قرأ...... ﴿قُلْ يَا أَيُّهَا الْكَافِرُونَ﴾ عدلت له بربع القرآن ومن قرأ ﴿قُلْ هُوَ اللَّهُ أَحَدٌ﴾ عدلت له بثلث القرآن» .\n(حسن) [ت] عن أنس. الضعيفة ١٣٤٢، الترغيب ٢/٢٢٤."],[7034,"«من قرأ القرآن فليسأل الله به فإنه سيجيء أقوام يقرءون القرآن يسألون به الناس» .\n(حسن) [ت] عن ابن عمران. الصحيحة ٢٥٧."],[7035,"«من قرأ بمائة آية في ليلة كتب له قنوت ليلة» .\n(صحيح) [حم ن] عن تميم. الصحيحة ٦٤٤."],[7036,"٢٢٠٢ - \"من قرأ حرفا من كتاب الله فله به حسنة، والحسنة بعشر أمثالها لا أقول: ﴿الم﴾ حرف ولكن: ألف حرف ولام حرف وميم حرف\".\n(صحيح) [تخ ت ك] عن ابن مسعود. شرح الطحاوية ١٥٨، المشكاة ٢١٣٧."],[7037,"«من قرأ سورة الكهف في يوم الجمعة أضاء له من النور ما بين الجمعتين» ... [ك هق] عن أبي سعيد.\n(صحيح) صحيح الترغيب ٧٣٨، المشكاة ٢١٧٥، الإرواء ٦٢٦."],[7038,"«من قرأ سورة الكهف يوم الجمعة أضاء له النور ما بينه وبين البيت العتيق» .\n(صحيح) [هب] عن أبي سعيد. المصادر السابقة."],[7039,"«من قرأ ﴿قُلْ هُوَ اللَّهُ أَحَدٌ﴾ أحد عشر مرات بنى الله له بيتا في الجنة» .\n(صحيح) [حم] عن معاذ بن أنس. الصحيحة ٥٨٩."],[7040,"«من قرأ ﴿قُلْ هُوَ اللَّهُ أَحَدٌ﴾ فكأنما قرأ ثلث القرآن» .\n(صحيح) [حم ن الضياء] عن أبي. الترغيب ٢/٢٢٥: حم، ت، ن - أبي أيوب."],[7041,"«من قرن بين حجه وعمرته أجزأه لهما طواف واحد» .\n(صحيح) [حم] عن ابن عمر. التعليقات الجياد."],[7042,"«من قطع رحما أو حلف على يمين فاجرة رأى وباله قبل أن يموت» .\n(صحيح) [تخ] عن القاسم بن عبد الرحمن مرسلا. الصحيحة ١١٢١."],[7043,"«من قطع سدرة صوب الله رأسه في النار» .\n(صحيح) [د الضياء] عن عبد الله بن حبشي. الصحيحة ٦١٤."],[7044,"٢٢٠٣ - \"من قعد مقعدا لم يذكر الله فيه كانت عليه من الله ترة ومن اضطجع مضجعا لا يذكر الله فيه كانت عليه من الله ترة\".\n(صحيح) [د] عن أبي هريرة. الصحيحة ٧٨."],[7045,"٢٢٠٤ - «من كاتب مملوكه على مائة أوقية فأداها إلا عشر أواق ثم عجز فهو رقيق» .\n(حسن) [ت] عن ابن عمرو. الإرواء ١٦٧٤."],[7046,"«من كان آخر كلامه لا إله إلا الله دخل الجنة» .\n(صحيح) [حم د ك] عن معاذ. المشكاة ١٦٢١، الإرواء ٦٨٧، أحكام الجنائز ٣٤."],[7047,"٢٢٠٥ - «من كان بينه وبين قوم عهد فلا يشد عقدة ولا يحلها حتى ينقضي أمدها أو ينبذ إليهم على سواء» .\n(صحيح) [حم د ت] عن عمروبن عبسة. الصحيحة ٢٣٥٧: الطيالسي."],[7048,"«من كان حالفا فلا يحلف إلا بالله» .\n(صحيح) [ن] عن ابن عمر. مختصر مسلم ١٠١١، الإرواء ٢٥٦٠: حم، ق١."],[7049,"٢٢٠٦ - «من كان ذبح أضحيته قبل أن يصلي فليذبح مكانها أخرى ومن لم يكن ذبح فليذبح باسم الله» .\n(صحيح) [حم ق ن هـ] عن جندب. مختصر مسلم ١٢٥٢، الإرواء ١١٥٣."],[7050,"٢٢٠٧ - «من كان ذبح قبل الصلاة فليعد» .\n(صحيح) [حم ق ن هـ] عن أنس. الإرواء ١١٥٣."],[7051,"«من كان سهلا هينا لينا حرمه الله على النار» .\n(صحيح) [ك هق] عن أبي هريرة. الصحيحة ٩٣٨: طس، عق."],[7052,"(١) قلت: وقد مضى لفظهم برقم ١٩٢٣."],[7053,"«من كان في المسجد ينتظر الصلاة فهو في الصلاة ما لم يحدث» .\n(صحيح) [حم ن حب] عن سهل بن سعد. الترغيب ١/١٦٠."],[7054,"٢٢٠٨ - «من كان لنا عاملا فلم يكن له زوجة فليكتسب له زوجة فإن لم يكن له خادم فليكتسب له خادما فإن لم يكن له مسكن فليكتسب مسكنا من اتخذ غير ذلك فهو غال أو سارق» .\n(صحيح) [د ك] عن المستورد بن شداد. المشكاة ٣٧٥١."],[7055,"«من كان له إمام فقراءة الإمام له قراءة» .\n(حسن) [حم هـ] عن جابر. صفة الصلاة ٨١."],[7056,"«من كان له ثلاث بنات فصبر عليهن وأطعمهن وسقاهن وكساهن من جدته كن له حجابا من النار يوم القيامة» .\n(صحيح) [حم هـ] عن عقبة بن عامر. الصحيحة ٢٩٣، ١٠٢٧."],[7057,"٢٢٠٩ - «من كان له ذبح يذبحه فإذا أهل هلال ذي الحجة فلا يأخذن من شعره ولا من أظفاره شيئا حتى يضحي» .\n(صحيح) [م د] عن أم سلمة. مختصر مسلم ١٢٥١، الإرواء ١١٦٣."],[7058,"«من كان له سعة ولم يضح فلا يقربن مصلانا» .\n(صحيح) [هـ ك] عن أبي هريرة. تخريج مشكلة الفقر ١٠٢."],[7059,"٢٢١٠ - «من كان له شريك في حائط فلا يبع نصيبه من ذلك حتى يعرضه على شريكه» .\n(صحيح) [حم ت ك] عن جابر. الإرواء ١٥٣٢."],[7060,"٢٢١١ - «من كان له شريك في ربع أو نخل فليس له أن يبيع حتى يؤذن شريكه فإن رضي أخذ وإن كره ترك» .\n(صحيح) [م] عن جابر."],[7061,"«من كان له شعر فليكرمه» .\n(صحيح) [د] عن أبي هريرة. الصحيحة ٥٠٠."],[7062,"«من كان له مال فلير عليه أثره» ... [طب] عن أبي حازم.\n(صحيح) الروض النضير ٨٥٢: الطيالسي، حم، ن، ك، طص، ابن مندة، ابن عبد البر - مالك بن نضلة."],[7063,"٢٢١٢ - «من كان له نخل أو أرض فلا يبعها حتى يعرضها على شريكه» .\n(صحيح) [هـ] عن جابر. الإرواء ١٥٣٢: م١."],[7064,"«من كان له وجهان في الدنيا كان له يوم القيامة لسانان من نار» .\n(صحيح) [د] عن عمار. الصحيحة ٨٩٢."],[7065,"٢٢١٣ - «من كان معه فضل ظهر فليعد به على من لا ظهر له ومن كان له فضل من زاد فليعد به على من لا زاد له» .\n(صحيح) [حم م د] عن أبي سعيد. مختصر مسلم ١٠٦٦، تخريج مشكلة الفقر ١١١."],[7066,"٢٢١٤ - «من كان منكم ذا طول فليتزوج فإنه أغض للبصر وأحصن للفرج ومن لا فالصوم له وجاء» .\n(صحيح) [ن] عن عثمان. الترغيب ٣/٦٧: حم."],[7067,"٢٢١٥ - «من كان منكم مصليا بعد الجمعة فليصل أربعا» .\n(صحيح) [د ت] عن أبي هريرة. صحيح أبي داود ١٠٣٦، الإرواء ٦١٨: م١."],[7068,"(١) وزاد في رواية: [فإن شاء أخذ، وإن شاء ترك، فإذا باع، ولم يؤذنه فهو أحق به] . وقد مضى بنحوه ٣٧٣٥. وهذا من الحقوق التي أهملها أكثر المسلمين اليوم، وفيهم من يتظاهر بالسلفية، وساعدهم على ذلك إلغاء حق الشفعة من بعض المحاكم الشرعية. نسأل الله السلامة."],[7069,"٢٢١٦ - «من كان يؤمن بالله واليوم الآخر فإذا شهد أمرا فليتكلم بخير أو ليسكت واستوصوا بالنساء فإن المرأة خلقت من ضلع وإن أعوج شيء في الضلع أعلاه إن ذهبت تقيمه كسرته وإن تركته لم يزل أعوج استوصوا بالنساء» .\n(صحيح) [م] عن أبي هريرة. مختصر مسلم ٨٤٤."],[7070,"«من كان يؤمن بالله واليوم الآخر فليحسن إلى جاره ومن كان يؤمن بالله واليوم الآخر فليكرم ضيفه ومن كان يؤمن بالله واليوم الآخر فليقل خيرا أو ليسكت» .\n(صحيح) [حم ق ن هـ] عن أبي شريح وأبي هريرة. مختصر مسلم ٣٢."],[7071,"٢٢١٧ - «من كان يؤمن بالله واليوم الآخر فليكرم ضيفه جائزته يوم وليلة والضيافة ثلاثة أيام فما بعد ذلك فهو صدقة ولا يحل له أن يثوي عنده حتى يخرجه» .\n(صحيح) [حم ق ٤] عن أبي شريح. المشكاة ٢٢٤٤، الإرواء ٢٥٢٣، ك ٤/١٦٤."],[7072,"٢٢١٨ - «من كان يؤمن بالله واليوم الآخر فلا يأخذن إلا مثلا بمثل» - يعني الذهب بالذهب.\n(صحيح) [م] عن فضالة بن عبيد. أحاديث البيوع."],[7073,"٢٢١٩ - «من كان يؤمن بالله واليوم الآخر فلا يؤذ جاره واستوصوا بالنساء خيرا» .\n(صحيح) [خ] عن أبي هريرة."],[7074,"(١) قلت: وزاد هو وغيره: قال سهيل: فإن عجل بك شيء فصل ركعتين في المسجد، وركعتين إذا رجعت.قلت: فهذا موقوف على سهيل. وفي رواية على أبيه أبي صالح، وقد توهم بعض الطلاب أنه مرفوع فتبنى التفصيل المذكور وهو خطأ. فتنبه."],[7075,"٢٢٢٠ - «من كان يؤمن بالله واليوم الآخر فلا يدخل الحمام إلا بمئزر» ... [ن] عن جابر.\n(صحيح) صحيح الترغيب ١٥٩، غاية المرام ١٩٠، الإرواء ٢٠٠٩، آداب الزفاف٥٩."],[7076,"«من كان يؤمن بالله واليوم الآخر فلا يدخل الحمام بغير إزار ومن كان يؤمن بالله واليوم الآخر فلا يدخل حليلته الحمام ومن كان يؤمن بالله واليوم الآخر فلا يجلس على مائدة يدار عليها الخمر» .\n(حسن) [ت ك] عن جابر. المصادر السابقة."],[7077,"٢٢٢١ - «من كان يؤمن بالله واليوم الآخر فلا يسق ماءه زرع غيره ومن كان يؤمن بالله واليوم الآخر فلا يأت سبيا من السبي حتى يستبرئها ومن كان يؤمن بالله واليوم الآخر فلا يبيعن مغنما حتى يقسم ومن كان يؤمن بالله واليوم الآخر فلا يركبن دابة من فيء المسلمين حتى إذا أعجفها ردها فيه ومن كان يؤمن بالله واليوم الآخر فلا يلبسن ثوبا من فيء المسلمين حتى إذا أخلقه رده فيه» .\n(حسن) [د] عن رويفع بن ثابت. الإرواء ٢١٣٧."],[7078,"«من كان يؤمن بالله واليوم الآخر فلا يسق ماءه ولد غيره» .\n(صحيح) [ت] عن رويفع. الإرواء ٢١٣٧."],[7079,"«من كان يؤمن بالله واليوم الآخر فلا يلبس حريرا ولا ذهبا» .\n(صحيح) [حم ك] عن أبي أمامة. الصحيحة ٣٣٧."],[7080,"٢٢٢٢ - «من كانت الآخرة همه جعل الله غناه في قلبه وجمع له شمله وأتته الدنيا وهي راغمة ومن كانت الدنيا همه جعل الله فقره بين عينيه وفرق عليه شمله ولم يأته من الدنيا إلا ما قدر له» .\n(صحيح) [ت] عن أنس. الصحيحة ٩٤٩ - ٩٥٠."],[7081,"٢٢٢٣ - «من كانت لأخيه عنده مظلمة من عرض أو مال فليتحلله اليوم قبل أن يؤخذ منه يوم لا دينار ولا درهم فإن كان له عمل صالح أخذ منه بقدر مظلمته وإن لم يكن له عمل أخذ من سيئات صاحبه فجعلت عليه» .\n(صحيح) [حم خ] عن أبي هريرة. شرح الطحاوية ٣٧٨، الضعيفة ٣٦٤١."],[7082,"٢٢٢٤ - «من كانت له أرض فأراد بيعها فليعرضها على جاره» .\n(صحيح) [هـ] عن ابن عباس. الصحيحة ٢٣٥٨: الضياء."],[7083,"٢٢٢٥ - «من كانت له أرض فليزرعها أو ليزرعها أخاه ولا يكرها بثلث ولا ربع ولا بطعام مسمى» .\n(صحيح) [حم د هـ] عن رافع بن خديج. م ٥/٢٣١."],[7084,"٢٢٢٦ - «من كانت له أرض فليزرعها فإن لم يستطع أن يزرعها وعجز عنها فليمنحها أخاه المسلم ولا يؤاجرها فإن لم يفعل فليمسك أرضه» .\n(صحيح) [حم ق ن هـ] عن جابر [ق ن] عن أبي هريرة [حم ت ن] عن رافع بن خديج [حم د] عن رافع بن رفاعة."],[7085,"٢٢٢٧ - «من كانت له امرأتان فمال إلى إحداهما جاء يوم القيامة وشقه مائل» ... [حم د ن هـ] عن أبي هريرة.\n(صحيح) الصحيحة ٢٠٧٧: الترغيب ٣/٧٩: الطيالسي، حب، ك. الإرواء ٢١٧."],[7086,"٢٢٢٨ - \"من كانت همه الآخرة جمع الله له شمله، وجعل غناه في قلبه وأتته الدنيا راغمة ومن كانت همه الدنيا فرق الله عليه أمره وجعل فقره بين عينيه ولم يأته من الدنيا إلا ما كتب الله له\".\n(صحيح) [هـ] عن زيد بن ثابت. الصحيحة ٩٤٩: حب."],[7087,"«من كتم علما عن أهله ألجم يوم القيامة لجاما من نار» ... [عد] عن ابن مسعود.\n(صحيح) صحيح الترغيب ١/٧٣، تحذير الساجد ص ٤: حب، ك - ابن عمرو."],[7088,"٢٢٢٩ - «من كتم غيظا وهو قادر على أن ينفذه دعاه الله على رءوس الخلائق حتى يخيره من الحور العين يزوجه منها ما شاء» .\n(حسن) [٤] عن معاذ بن أنس. الترغيب ٣/٢٧٩: حم، حل، هـ."],[7089,"«من كذب علي متعمدا فليتبوأ مقعده من النار» .\n(صحيح متواتر) [حم ق ت ن هـ] عن أنس [١] ... [حم خ د ن هـ] عن الزبير [٢] ... [م] عن أبي هريرة [٣] ... [ت] عن علي [٤] ... [حم هـ] عن جابر [٥] . وعن أبي سعيد [٦] ... [ت هـ] عن ابن مسعود [٧] ... [حم ك] عن خالد بن عرفطة [٨]، وعن زيد بن أرقم [٩] ... [حم] عن سلمة بن الأكوع [١٠]، وعن عقبة بن عامر [١١]، وعن معاوية بن أبي سفيان [١٢] ... [طب] عن السائب بن يزيد [١٣]، وعن سلمان بن خالد الخزاعي [١٤]، وعن صهيب [١٥]، وعن طارق بن أشيم [١٦]، وعن طلحة بن عبيد الله [١٧]، وعن ابن عباس [١٨]، وعن ابن عمر [١٩]، وعتبة بن غزوان [٢٠]، وعن العرس بن عميرة [٢١]، وعن عمار بن ياسر [٢٢]، وعن عمران بن حصين [٢٣]، وعن عمرو بن حريث [٢٤]، وعن عمرو بن عبسة [٢٥]، وعن عمرو بن مرة الجهني [٢٦]، وعن المغيرة بن شعبة [٢٧]، وعن يعلى بن مرة [٢٨]، وعن أبي عبيدة بن الجراح [٢٩]، وعن أبي موسى الأشعري [٣٠] ... [طس] عن البراء [٣١]، وعن معاذ بن جبل [٣٢]، وعن نبيط بن شريط [٣٣]، وعن أبي ميمون [٣٤] ... [قط في] الأفراد [\" عن أبي رمثة] ٣٥ [، وعن ابن الزبير] ٣٦ [، وعن أبي رافع] ٣٧ [، وعن أم أيمن] ٣٨ [...] خط [عن سلمان الفارسي] ٣٩ [، وعن أبي أمامة] ٤٠ [...] ابن عساكر [عن رافع بن خديج] ٤١ [، وعن يزيد بن أسد] ٤٢ [، وعن عائشة] ٤٣ [...] ابن صاعد في [طرقه] [عن أبي بكر الصديق] ٤٤ [، وعن عمر بن الخطاب] ٤٥ [، وعن سعد بن أبي وقاص] ٤٦ [، وعن حذيفة بن أسيد] ٤٧ [، وعن حذيفة بن اليمان] ٤٨ [...] أبو مسعود بن الفرات في [جزئه] [عن عثمان بن عفان] ٤٩ [...] البزار [عن سعيد بن زيد] ٥٠ [...] عد [عن أسامة بن زيد] ٥١ [، وعن بريدة] ٥٢\"، وعن سفينة [٥٣]، وعن أبي قتادة [٥٤] ... [أبو نعيم في] المعرفة [\" عن جندع بن عمرو] ٥٥ [، وعن سعد بن المدحاس] ٥٦ [، وعن عبد الله بن زغب] ٥٧ [...] ابن قانع [عن عبد الله بن أبي أوفى] ٥٨ [...] ك في المدخل [عن عفان بن حبيب] ٥٩ [...] عق [عن غزوان] ٦٠ [، وعن أبي كبشة] ٦١ [...] ابن الجوزي في [مقدمة الموضوعات] ١ [عن أبي ذر] ٦٢ [، وعن أبي موسى الغافقي] ٦٣\"\". الروض النضير ٧٠٧، مختصر مسلم ١٨٦١، ١٨٦٢."],[7090,"«من كذب في حلمه كلف يوم القيامة عقد شعيرة» .\n(صحيح) [حم ت ك] عن علي. الصحيحة ٢٣٥٩: الدارمي، عم - علي. خ، ت - ابن عباس."],[7091,"٢٢٣٠ - «من كسر أو مرض أو عرج فقد حل وعليه حجة أخرى من قابل» .\n(صحيح) [حم ٤ ك] عن الحجاج بن عمرو بن غزية. المشكاة ٢٧١٣."],[7092,"٢٢٣١ - «من كظم غيظا وهو قادر على أن ينفذه دعاه الله على رءوس الخلائق حتى يخيره من الحور العين يزوجه منها ما شاء» .\n(حسن) [٤] عن معاذ بن أنس. المشكاة ٥٠٨٨، الروض النضير ٨٥٤: حم، طص."],[7093,"«من كنت مولاه فعلي مولاه» .\n(صحيح) [حم هـ] عن البراء [حم] عن بريدة [ت ن الضياء] عن زيد بن أرقم. الصحيحة ١٧٥٠، الروض النضير ١٧١، المشكاة ٦٠٨٢."],[7094,"«من كنت وليه فعلي وليه» .\n(صحيح) [حم ن ك] عن بريدة. الروض النضير ١٧١: طص."],[7095,"«من لبس الحرير في الدنيا لم يلبسه في الآخرة» .\n(صحيح) [حم ق ن هـ] عن أنس. الصحيحة ٣٨٤."],[7096,"(١) ١/٥٧، ٩٢. قلت وراه ص ٧٢ عن عبد الله بن عمرو أيضا وص ٨٤ عن واثلة بن الأسقع و٨٥ عن قيس بن سعد، و٨٨ عن أبي قرصافة جندرة بن خيشنة و٨٩ عن أبي رافع مولى رسول الله صلى الله عليه وآله وسلم و٩١ عن رجل من أسلم من الصحابة، وعن رجلين آخرين من الصحابة."],[7097,"«من لبس ثوب شهرة ألبسه الله يوم القيامة ثوبا مثله ثم يلهب فيه النار» .\n(حسن) [د هـ] عن ابن عمر. حجاب المرأة المسلمة ١١٠."],[7098,"«من لطم مملوكه أو ضربه فكفارته أن يعتقه» .\n(صحيح) [حم م د] عن ابن عمر. الإرواء ٢١٧٣."],[7099,"٢٢٣٢ - «من لعب بالنردشير فكأنما غمس يده في لحم الخنزير ودمه» .\n(صحيح) [حم م د هـ] عن بريدة. مختصر مسلم ١٥١١، الإرواء ٢٦٧٠."],[7100,"«من لعب بالنرد فقد عصى الله ورسوله» .\n(حسن) [حم د هـ ك] عن أبي موسى. الإرواء ٢٦٧٠."],[7101,"«من لعب بطلاق أو عتاق فهو كما قال» .\n(حسن) [طب] عن أبي الدرداء. الإرواء ١٨٢٦."],[7102,"«من لقي الله لا يشرك به شيئا دخل الجنة» .\n(صحيح) [حم خ] عن أنس. التوحيد ٣٣٣ - عن جابر."],[7103,"٢٢٣٣ - «من لكعب بن الأشرف؟ فإنه قد آذى الله ورسوله» .\n(صحيح) [خ] عن جابر. مختصر مسلم ١١٧٠."],[7104,"«من لم يأخذ من شاربه١ فليس منا» .\n(صحيح) [حم ت ن الضياء] عن زيد بن أرقم. الروض النضير ٣١٣، المشكاة ٤٤٣٨."],[7105,"(١) هذا الحديث يدل على أن المشروع في الشارب أن يؤخذ منه بعضه، وهو ما طال على الشفة، وأما أخذه كله كما يفعله بعض الصوفية وغيرهم. فهو كما قال مالك مثلة. وقد وجدت له شاهدا أن حجاما أخذ من شارب النبي صلى الله عليه وآله وسلم. أخرجه ابن سعد ١/٤٣٣، وله عنده ١/٤٤٩ شاهد آخر."],[7106,"«من لم يبيت الصيام قبل طلوع الفجر فلا صيام له» .\n(صحيح) [قط هق] عن عائشة. الإرواء ٩١٤."],[7107,"٢٢٣٤ - «من لم يبيت الصيام من الليل فلا صيام له» .\n(صحيح) [ن] عن حفصة. الإرواء ٩١٤."],[7108,"٢٢٣٥ - «من لم يجد نعلين فليلبس خفين وليقطعهما أسفل من الكعبين» .\n(صحيح) [خ] عن ابن عمر. الإرواء ١٠١٢."],[7109,"٢٢٣٦ - «من لم يجد نعلين فليلبس خفين ومن لم يجد إزارا فليلبس سرأويل. - يعني - المحرم» .\n(صحيح) [حم م] عن جابر [حم ق ن هـ] عن ابن عباس. الإرواء ١٠١٢."],[7110,"«من لم يجمع الصيام قبل الفجر فلا صيام له» .\n(صحيح) [حم ٣] عن حفصة. الإرواء ٩١٤."],[7111,"«من لم يدع قول الزور والعمل به فليس لله حاجة في أن يدع طعامه وشرابه» .\n(صحيح) [حم خ د ت] عن أبي هريرة. الروض النضير ١١٨."],[7112,"«من لم يرحم صغيرنا ويعرف حق كبيرنا فليس منا١» .\n(صحيح) [خد د] عن ابن عمرو. صحيح الترغيب ٩٨."],[7113,"«من لم يشكر الناس لم يشكر الله» .\n(صحيح) [حم ت الضياء] عن أبي سعيد. الصحيحة ٤١٧."],[7114,"\"من لم يصل ركعتي الفجر فليصلها بعد ما تطلع الشمس [...] حم ت ك\" عن أبي هريرة.\n(صحيح) الصحيحة ٢٣٦١: ابن خزيمة، حب، هق."],[7115,"(١) تقدم نحوه برقم ٥٤٤٤."],[7116,"«من مات على شيء بعثه الله عليه» .\n(صحيح) [حم ك] عن جابر. الصحيحة ٢٨٣."],[7117,"٢٢٣٧ - «من مات مرابطا في سبيل الله أجرى الله عليه عمله الصالح الذي كان يعمل عليه وأجرى عليه رزقه وأمن من الفتان وبعثه الله يوم القيامة آمنا من الفزع» .\n(صحيح) [هـ] عن أبي هريرة. الترغيب ٢/١٥١، الضعيفة ٤٦٥٩: أبو عوانة."],[7118,"«من مات مرابطا في سبيل الله أمنه الله من فتنة القبر» .\n(صحيح) [طب] عن أبي أمامة. الترغيب ٢/١٥٠: طس."],[7119,"٢٢٣٨ - «من مات وعليه دينار أو درهم قضي من حسناته ليس ثم دينار ولا درهم» .\n(صحيح) [هـ] عن ابن عمر. أحكام الجنائز ٥."],[7120,"«من مات وعليه صيام صام عنه وليه» .\n(صحيح) [حم ق د] عن عائشة. مختصر مسلم ٦٠٥."],[7121,"٢٢٣٩ - «من مات ولم يغز ولم يحدث نفسه بغزو مات على شعبة من نفاق» .\n(صحيح) [حم م د ن] عن أبي هريرة. مختصر مسلم ١٠٧٣."],[7122,"«من مات وهو مدمن خمر لقي الله وهو كعابد وثن» .\n(صحيح) [طب حل] عن ابن عباس. الصحيحة ٦٧٧."],[7123,"«من مات لا يشرك بالله شيئا دخل الجنة» .\n(صحيح) [حم ق] عن ابن مسعود."],[7124,"٢٢٤٠ - «من مات لا يشرك بالله شيئا دخل الجنة ومن مات يشرك بالله شيئا دخل النار» .\n(صحيح) [حم م] عن جابر. مختصري لصحيح البخاري [٢٣ - الجنائز/١تعليق]: ابن خزيمة. مختصر مسلم ٥٢."],[7125,"٢٢٤١ - «من مات وهو يعلم أن لا إله إلا الله دخل الجنة» .\n(صحيح) [حم م] عن عثمان. مختصر مسلم ٩."],[7126,"«من مس الحصى١ فقد لغا» .\n(صحيح) [هـ] عن أبي هريرة. صحيح أبي داود ٩٦٤."],[7127,"«من مس ذكره فليتوضأ» .\n(صحيح) [مالك حم ٤ ك] عن بسرة بنت صفوان. الروض النضير ١٧٤، المشكاة ٣١٩، صحيح أبي داود ١٧٤، الإرواء ١١٦."],[7128,"٢٢٤٢ - «من مس فرجه فليتوضأ» .\n(صحيح) [هـ] عن أم حبيبة وأبي أيوب. المصادر السابقة."],[7129,"«من مشى إلى صلاة مكتوبة في الجماعة فهي كحجة ومن مشى إلى صلاة تطوع٢ فهي كعمرة نافلة» .\n(حسن) [طب] عن أبي أمامة. صحيح أبي داود ٥٦٧: حم، د، عد، هق، ابن عساكر."],[7130,"«من ملك ذا رحم محرم فهو حر» .\n(صحيح) [حم د ت هـ ك] عن سمرة. الإرواء ١٧٤٦."],[7131,"«من منح منحة غدت بصدقة وراحت بصدقة صبوحها وغبوقها» .\n(صحيح) [م] عن أبي هريرة."],[7132,"(١) يعني والخطيب يخطب يوم الجمعة كما يدل عليه سياق الحديث عند مسلم وغيره، وقد مضى بلفظ: [من توضأ يوم الجمعة، فأحسن الوضوء.. ...] برقم ٦١٧٩.٢ قلت: يعني صلاة الضحى كما في رواية [د] وغيره."],[7133,"«من منح منحة ورق أو منحة لبن أو أهدى زقاقا فهو كعتق نسمة» .\n(صحيح) [حم ت حب] عن البراء. المشكاة ١٩١٧، صحيح الترغيب ٨٨٩و ٢/٢٤١."],[7134,"«من منع فضل ماء أو كلأ منعه الله فضله يوم القيامة» .\n(صحيح) [حم] عن ابن عمرو. الصحيحة ١٤٢٢."],[7135,"٢٢٤٣ - «من نام عن حزبه أو عن شيء منه فقرأه فيما بين صلاة الفجر وصلاة الظهر كتب الله له كأنما قرأه من الليل» .\n(صحيح) [م] عن عمر. صحيح أبي داود ١١٨٦."],[7136,"«من نام عن وتره أو نسيه فليصله إذا ذكره» .\n(صحيح) [حم ٤ ك] عن أبي سعيد. المشكاة ١٢٦٨، ١٢٧٩، الإرواء ٤٤٢."],[7137,"٢٢٤٤ - «من نام عن وتره فليصل إذا أصبح» .\n(صحيح) [ت] عن زيد بن أسلم مرسلا. الإرواء ٤٢٢: حم، مج، ابن نصر - عن أبي سعيد."],[7138,"٢٢٤٥ - «من نام وفي يده غمر ولم يغسله فأصابه شيء فلا يلومن إلا نفسه» .\n(صحيح) [حم د] عن أبي هريرة. الروض النضير ٨٢٣."],[7139,"«من نذر أن يطيع الله فليطعه ومن نذر أن يعصي الله فلا يعصه» .\n(صحيح) [حم خ ٤] عن عائشة. الإرواء ٩٦٧."],[7140,"٢٢٤٦ - \"من نزلت به فاقة فأنزلها بالناس لم تسد فاقته ومن نزلت به فاقة فأنزلها بالله فيوشك الله له برزق عاجل أو آجل\".\n(صحيح) [ت] عن ابن مسعود. صحيح الترغيب و٢٧٣ ٨٣١: حم، د، طب، ك، حل."],[7141,"٢٢٤٧ - «من نزل منزلا فقال: أعوذ بكلمات الله التامات من شر ما خلق لم يضره شيء حتى يرتحل من منزله» .\n(صحيح) [حم م د ت] عن خولة بنت حكيم. مختصر مسلم ١٤٥٩."],[7142,"«من نسي الصلاة علي خطئ طريق الجنة» .\n(صحيح) [هـ] عن ابن عباس. الترغيب ٢/٢٨٤، فضل الصلاة ٤١ - ٤٤."],[7143,"٢٢٤٨ - «من نسي الصلاة فليصلها إذا ذكرها فإن الله قال: ﴿وَأَقِمِ الصَّلاةَ لِذِكْرِي﴾ ١» .\n(صحيح) [م د ن هـ] عن أبي هريرة. صحيح أبي داود ٤٦١، الإرواء ٢٦٣."],[7144,"٢٢٤٩ - «من نسي شيئا من صلاته فليسجد سجدتين وهو جالس» .\n(حسن) [حم ن] عن معاوية. ضعيف أبي داود ١٩٠."],[7145,"«من نسي صلاة أو نام عنها فكفارتها أن يصليها إذا ذكرها» .\n(صحيح) [حم ق ت ن] عن أنس. صحيح أبي داود ٤٦٨."],[7146,"٢٢٥٠ - «من نسي صلاة فليصلها إذا ذكرها لا كفارة لها إلا ذلك» .\n(صحيح) [د ت هـ] عن أنس. صحيح أبي داود ٤٦٨."],[7147,"\"من نسي وهو صائم فأكل أو شرب فليتم صومه، فإنما أطعمه الله وسقاه\".\n(صحيح) [حم ق هـ] عن أبي هريرة. مختصر مسلم ٥٨٧، الإرواء ٩٣٨."],[7148,"(١) وفي رواية لمسلم وأبي داود [للذكرى] وهي محفوظة كما بينته في المصدر المذكور."],[7149,"«من نصر أخاه بظهر الغيب نصره الله في الدنيا والآخرة» .\n(حسن) [هق الضياء] عن أنس. الصحيحة ١٢١٧."],[7150,"٢٢٥١ - «من نصر قومه على غير الحق فهو كالبعير الذي تردى فهو ينزع بذنبه» .\n(صحيح) [د] عن ابن مسعود. المشكاة ٤٩٠٤: حم، حب، ك."],[7151,"«من نفس عن غريمه أو محا عنه كان في ظل العرش يوم القيامة» .\n(صحيح) [حم م] عن أبي قتادة. صحيح الترغيب ٩٠٢: الدارمي."],[7152,"٢٢٥٢ - «من نفس عن مؤمن كربة من كرب الدنيا نفس الله عنه كربة من كرب يوم القيامة ومن يسر على معسر يسر الله عليه في الدنيا والآخرة ومن ستر مسلما ستره الله في الدنيا والآخرة والله في عون العبد ما كان العبد في عون أخيه ومن سلك طريقا يلتمس فيه علما سهل الله له طريقا إلى الجنة وما اجتمع قوم في بيت من بيوت الله يتلون كتاب الله ويتدارسونه بينهم إلا نزلت عليهم السكينة وغشيتهم الرحمة وحفتهم الملائكة وذكرهم الله فيمن عنده ومن أبطأ به عمله لم يسرع به نسبه» ... [حم م د ت هـ] عن أبي هريرة.\n(صحيح) مختصر مسلم ١٨٨٨، صحيح الترغيب ٦٧."],[7153,"«من نوقش الحساب عذب» .\n(صحيح) [ق] عن عائشة."],[7154,"«من نوقش المحاسبة هلك» .\n(صحيح) [طب] عن ابن الزبير. المشكاة ٥٥٦٢: حم، ك - عن عائشة."],[7155,"«من نيح عليه يعذب بما نيح عليه» .\n(صحيح) [حم ق ت] عن المغيرة. أحكام الجنائز ٢٩: هق."],[7156,"«من هجر أخاه سنة فهو كسفك دمه» .\n(صحيح) [حم خد د ك] عن حدرد. الصحيحة ٩٢٨: ابن سعد."],[7157,"٢٢٥٣ - «من هذا اللاعن بعيره؟! أنزل عنه فلا تصحبنا بملعون لا تدعوا على أنفسكم ولا تدعوا على أولادكم ولا تدعوا على أموالكم لا توافقوا من الله ساعة يسأل فيها عطاء فيستجيب لكم» .\n(صحيح) [م د] عن جابر. مختصر مسلم ١٥٣٧."],[7158,"«من وجد تمرا فليفطر عليه ومن لا فليفطر على الماء فإنه طهور» ... [ت ن ك] عن أنس.\n(صحيح) الإرواء ٩٢٢، صحيح الترغيب ١٠٧٠، الروض النضير ١٢٢: ابن خزيمة، طص، هق. ابن خزيمة - سليمان١."],[7159,"٢٢٥٤ - «من وجد دابة قد عجز عنها أهلها أن يعلفوها فسيبوها فأخذها فأحياها فهي له» .\n(حسن) [د] عن رجال من الصحابة. الإرواء ١٥٦٢."],[7160,"«من وجد سعة فليكفن في ثوب حبرة» .\n(صحيح) [حم] عن جابر. أحكام الجنائز ٦٣."],[7161,"٢٢٥٥ - «من وجد لقطة فليشهد ذوي عدل ولا يكتم ولا يعبث فإن وجد صاحبها فليردها عليه وإلا فهو مال الله يؤتيه من يشاء» .\n(صحيح) [حم د هـ] عن عياض بن حمار. المشكاة ٣٠٣٩."],[7162,"(١) قلت: وتقدم لفظه برقم ٣٦٣."],[7163,"«من وجد من هذا الوسواس فليقل: آمنا بالله ورسوله؛ ثلاثا فإن ذلك يذهب عنه» .\n(صحيح) [ابن السني] عن عائشة. الصحيحة ١١٦: عد."],[7164,"٢٢٥٦ - «من وجدتموه وقع على بهيمة فاقتلوه واقتلوا البهيمة» .\n(صحيح) [ت ك] عن ابن عباس. الإرواء ٢٣٤٨."],[7165,"٢٢٥٧ - «من وجدتموه يعمل عمل قوم لوط فاقتلوا الفاعل والمفعول به» .\n(صحيح) [حم ٤ قط ك الضياء] عن ابن عباس. الإرواء ٢٣٥٠."],[7166,"«من وصل صفا وصله الله ومن قطع صفا قطعه الله» .\n(صحيح) [ن ك] عن ابن عمر."],[7167,"«من وضع الخمر.......، ومن أدمن على شربها سقي من الخبال» .\n(صحيح) [طب] عن ابن عمر. مجمع الزوائد ٥/٧٢."],[7168,"«من وطئ على إزار خيلاء وطئه في النار» .\n(صحيح) [حم] عن هبيب١. الترغيب ٣/٩٩: تخ."],[7169,"«من وقاه الله شر ما بين لحييه وشر ما بين رجليه دخل الجنة» .\n(صحيح) [ت حب ك] عن أبي هريرة. الصحيحة ٥١٠."],[7170,"(١) الأصل: صهيب تبعا لأصله، وهو خطأ انطلى أمره على المناوي، فقيده بقوله: بضم المهملة الرومي! والتصويب من المصدرين المذكورين أعلاه."],[7171,"«من ولي القضاء فقد ذبح بغير سكين» .\n(حسن) [د ت] عن أبي هريرة. الترغيب ٣/١٣١، الروض النضير ١١٣٦، المشكاة ٣٧٣٣."],[7172,"٢٢٥٨ - «من ولي من أمور المسلمين شيئا فاحتجب دون خلتهم وحاجتهم وفقرهم وفاقتهم احتجب الله عنه يوم القيامة دون خلته وحاجته وفاقته وفقره» .\n(صحيح) [د هـ ك] عن أبي مريم الأزدي. الصحيحة ٦٢٩."],[7173,"٢٢٥٩ - «من ولي منكم عملا فأراد الله به خيرا جعل له وزيرا صالحا إن نسي ذكره وإن ذكر أعانه» .\n(صحيح) [ن] عن عائشة. الصحيحة ٤٨٩."],[7174,"«من لا يرحم الناس لا يرحمه الله» .\n(صحيح) [حم ق ت] عن جرير [حم ت] عن أبي سعيد."],[7175,"«من لا يرحم لا يرحم» .\n(صحيح) [حم ق د ت] عن أبي هريرة [ق] عن جرير. تخريج مشكلة الفقر ١٠٨."],[7176,"«من لا يرحم لا يرحم ومن لا يغفر لا يغفر له» .\n(صحيح) [حم] عن جرير. الترغيب ٣/١٥٤."],[7177,"«من لا يرحم لا يرحم ومن لا يغفر لا يغفر له ومن لا يتب لا يتب عليه» .\n(صحيح) [طب] عن جرير. الصحيحة ٤٨٣."],[7178,"«من لا يشكر الناس لا يشكر الله» .\n(صحيح) [ت] عن أبي هريرة. المشكاة ٣٠٢٥."],[7179,"٢٢٦٠ - \"من لايمكم من خدمكم فأطعموهم مما تأكلون وألبسوهم مما تلبسون ومن لا يلايمكم منهم فبيعوه ولا تعذبوا خلق الله\".\n(صحيح) [حم د] عن أبي ذر. الصحيحة ٧٣٩."],[7180,"٢٢٦١ - «من يتقبل لي بواحدة أتقبل له بالجنة لا يسأل الناس شيئا» .\n(صحيح) [حم ن هـ] عن ثوبان. المشكاة ١٨٥٧، صحيح الترغيب ٨٠٧."],[7181,"«من يتكفل لي أن لا يسأل الناس شيئا أتكفل له بالجنة» .\n(صحيح) [د ك] عن ثوبان. المصدران السابقان."],[7182,"٢٢٦٢ - «من يتوكل لي ما بين لحييه وما بين رجليه أتوكل له بالجنة» .\n(صحيح) [حم ت حب ك] عن سهل بن سعد. الترغيب ٣/١٩٧."],[7183,"«من يحرم الرفق يحرم الخير كله» .\n(صحيح) [حم م د هـ] عن جرير. مختصر مسلم ١٧٨٣."],[7184,"«من يخفر ذمتي كنت خصمه ومن خاصمته خصمته» .\n(حسن) [طب] عن جندب. صحيح الترغيب ١/١٦٣."],[7185,"«من يدخل الجنة ينعم فيها لا يبأس لا تبلى ثيابه ولا يفنى شبابه» .\n(صحيح) [م] عن أبي هريرة. مختصر مسلم ١٩٦٤، الصحيحة ١٠٨٥."],[7186,"«من يرائي يرائي الله به ومن يسمع يسمع الله به» .\n(صحيح) [حم ت هـ] عن أبي سعيد. خ: رقاق، م ٨/٢٢٣ - جندب. م - ابن عثمان."],[7187,"«من يرد الله به خيرا يصب منه» .\n(صحيح) [حم خ] عن أبي هريرة. المشكاة ١٥٣٦."],[7188,"«من يرد الله به خيرا يفقهه في الدين» .\n(صحيح) [حم ق] عن معاوية [حم ت] عن ابن عباس [هـ] عن أبي هريرة. الروض النضير ١١٤٩، الصحيحة ١١٩٤."],[7189,"٢٢٦٣ - «من يرد الله به خيرا يفقهه في الدين وإنما أنا قاسم والله يعطي ولن تزال هذه الأمة قائمة على أمر الله لا يضرهم من خالفهم حتى يأتي أمر الله عز وجل» .\n(صحيح) [حم ق] عن معاوية. الصحيحة ١١٩٥."],[7190,"«من يرد هوان قريش أهانه الله» .\n(صحيح) [حم ن ك] عن سعد. الصحيحة ١١٧٨: عد."],[7191,"«من يسر على معسر يسر الله عليه في الدنيا والآخرة» .\n(صحيح) [هـ] عن أبي هريرة\". صحيح الترغيب ٨٩٢: م، حب."],[7192,"٢٢٦٤ - «من يشرب النبيذ منكم فليشربه زبيبا فردا أو تمرا فردا أو بسرا فردا» .\n(صحيح) [م] عن أبي سعيد."],[7193,"٢٢٦٥ - «من يصعد الثنية ثنية المرار فإنه يحط عنه ما حط عن بني إسرائيل» .\n(صحيح) [م] عن جابر. مختصر مسلم ١٩٣٩."],[7194,"«من يضمن لي ما بين لحييه وما بين رجليه أضمن له الجنة» .\n(صحيح) [خ] عن سهل بن معاذ. الضعيفة ٢٣٠٢: المختارة - صعصعة."],[7195,"٢٢٦٦ - \"من يطيع الله إذا عصيته؟! أيأمنني الله على أهل الأرض ولا تأمنوني؟! إن من ضئضئ هذا قوما يقرءون القرآن لا يجأوز حناجرهم يمرقون من الدين مروق السهم من الرمية يقتلون أهل الإسلام ويدعون أهل الأوثان لئن أنا أدركتهم لأقتلنهم قتل عاد\".\n(صحيح) [خ] عن أبي سعيد. السنة ٩١٠: حم، م، د، ن. ابن أبي عاصم - علي."],[7196,"«من يكن في حاجة أخيه يكن الله في حاجته» .\n(صحيح) [ابن أبي الدنيا في قضاء الحوائج] عن جابر. الصحيحة ٢٣٦٣: حم، ق، د، ت - ابن عمر. حم - مسلمة بن مخلد."],[7197,"«منى مناخ من سبق» .\n(حسن) [ت هـ ك] عن عائشة. المشكاة ٢٦٢٥."],[7198,"«منبري هذا على ترعة من ترع الجنة» .\n(صحيح) [حم] عن أبي هريرة. الصحيحة ٢٣٦٣: ابن سعد، حم، سهل بن سعد، وجابر، وعبد الله بن زيد الأنصاري."],[7199,"٢٢٦٧ - «منزلنا غدا إن شاء الله بخيف بني كنانة حيث تقاسموا على الكفر» .\n(صحيح) [ق] عن أبي هريرة."],[7200,"٢٢٦٨ - «منعت العراق درهمها وقفيزها ومنعت الشام مدها ودينارها ومنعت مصر أردبها ودينارها وعدتم من حيث بدأتم وعدتم من حيث بدأتم وعدتم من حيث بدأتم» .\n(صحيح) [حم م د] عن أبي هريرة."],[7201,"«منهومان لا يشبعان: طالب علم وطالب دنيا» .\n(صحيح) [عد] عن أنس [البزار] عن ابن عباس. المشكاة ٢٦٠، العلم لأبي خيثمة ١٤١."],[7202,"«مه عليكم بما تطيقون من الأعمال فوالله لا يمل الله حتى تملوا» .\n(صحيح) [خ ن هـ] عن عائشة. صحيح أبي داود ١٢٣٨: حم، أبو عوانة."],[7203,"٢٢٦٩ - «مه يا عائشة! فإن الله لا يحب الفحش ولا التفحش» .\n(صحيح) [م] عن عائشة."],[7204,"٢٢٧٠ - «مهلا يا عائشة! عليك بالرفق وإياك والعنف والفحش» .\n(صحيح) [خ] عن عائشة."],[7205,"«مهلا يا خالد! لا تسبها فو الذي نفسي بيده لقد تابت توبة لوتابها صاحب مكس لغفر له» .\n(حسن) [حم م د ن] عن بريدة. الإرواء ٢٢٢٦."],[7206,"٢٢٧١ - «مهل أهل المدينة من ذي الحليفة وللطريق الآخر الجحفة ومهل أهل العراق من ذات عرق ومهل أهل نجد من قرن ومهل أهل اليمن من يلملم» .\n(صحيح) [م هـ] عن جابر. مختصر مسلم ٦٥٢، الإرواء ٩٩٦."],[7207,"«موالينا منا» .\n(صحيح) [طس] عن ابن عمر. الصحيحة ١٦١٢: خ - أنس."],[7208,"«موت الفجأة أخذة أسف» .\n(صحيح) [حم د] عن عبيد الله بن خالد. المشكاة ١٦١١."],[7209,"«موتان الأرض لله ولرسوله فمن أحيا منها شيئا فهو له» .\n(حسن) [هق] عن ابن عباس. الإرواء ١٥٤٩."],[7210,"«موسى بن عمران صفي الله» .\n(صحيح) [ك] عن أنس. الصحيحة ٢٣٦٤: الديلمي."],[7211,"٢٢٧٢ - «موضع الإزار إلى أنصاف الساقين والعضلة فإن أبيت فأسفل فإن أبيت فمن وراء الساق ولا حق للكعبين في الإزار» .\n(صحيح) [ن] عن حذيفة. الصحيحة ٢٣٦٦: حم، ت، هـ."],[7212,"«موضع سوط في الجنة خير من الدنيا وما فيها» .\n(صحيح) [خ ت هـ] عن سهل بن سعد [ت] عن أبي هريرة. الصحيحة ١٩٧٨: حم - سهل. حم، الدارمي، ك - أبي هريرة."],[7213,"٢٢٧٣ - «موقف ساعة في سبيل الله خير من قيام ليلة القدر عند الحجر الأسود» .\n(صحيح) [حب هب] عن أبي هريرة. الصحيحة ١٠٦٨، الترغيب ٢/١٥٢."],[7214,"«مولى القوم من أنفسهم» ... [خ] عن أنس.\n(صحيح) الصحيحة ١٢١٦: حم، د، ن، ت، الطحاوي، ك - أبي رافع١."],[7215,"«ميامين الخيل في شقرها» .\n(حسن) [الطيالسي] عن ابن عباس. الترغيب ٢/١٦٢."],[7216,"«ميتة البحر حلال وماؤه طهور» .\n(صحيح) [قط ك] عن ابن عمرو. صحيح أبي داود ٧٦: مالك، حم، ٤، الدارمي، قط، ك، هق - أبي هريرة."],[7217,"(١) قلت: وقد مضى حديثه برقم ١٦٦٣."],[7218,"فصل في المحلى بـ\"ال\" من هذا الحرف."],[7219,"٢٢٧٤ - «الماء طهور لا ينجسه شيء» .\n(صحيح) [حم] عن أبي سعيد [ن حب ك] عن ابن عباس. صحيح أبي داود ٥٩، الإرواء ١٤، المشكاة ٢٨٨."],[7220,"«الماء لا ينجسه شيء» .\n(صحيح) [طس] عن عائشة. المصادر السابقة."],[7221,"«المائد في البحر الذي يصيبه القيء له أجر شهيد والغريق له أجر شهيدين» .\n(صحيح) [د] عن أم حرام. الإرواء ١١٩٤، المشكاة ٣٨٣٩."],[7222,"«المؤذن يغفر له مد صوته وأجره مثل أجر من صلى معه» .\n(صحيح) [طب] عن أبي أمامة. صحيح الترغيب ٢٣١."],[7223,"«المؤذن يغفر له مدى صوته ويشهد له كل رطب ويابس وشاهد الصلاة يكتب له خمس وعشرون صلاة ويكفر عنه ما بينهما» .\n(صحيح) [حم د ن هـ حب] عن أبي هريرة. المشكاة ٦٦٧."],[7224,"«المؤذنون أطول الناس أعناقا يوم القيامة» .\n(صحيح) [حم م هـ] عن معاوية. مختصر مسلم ١٩٧."],[7225,"«المؤذنون أمناء المسلمين على صلاتهم وحاجتهم» .\n(حسن) [هق] عن الحسن مرسلا. الإرواء ١١٨."],[7226,"«المؤذنون أمناء المسلمين على فطرهم وسحورهم» .\n(حسن) [طب] عن أبي محذورة. المصدر السابق."],[7227,"٢٢٧٥ - «المؤمن أخوالمؤمن فلا يحل للمؤمن أن يبتاع على بيع أخيه ولا يخطب على خطبة أخيه حتى يذر» .\n(صحيح) [م] عن عقبة بن عامر. مختصر مسلم ٨٠٠، الإرواء ١٢٩٧."],[7228,"«المؤمن إذا اشتهى الولد في الجنة كان حمله ووضعه وسنه في ساعة واحدة كما يشتهي» .\n(صحيح) [حم ت هـ حب] عن أبي سعيد. المشكاة ٥٦٤٨."],[7229,"٢٢٧٦ - «المؤمن القوي خير وأحب إلى الله من المؤمن الضعيف وفي كل خير احرص على ما ينفعك واستعن بالله ولا تعجز وإن أصابك شيء فلا تقل: لو أني فعلت كان كذا وكذا ولكن قل: قدر الله وما شاء فعل فإن لو تفتح عمل الشيطان» ... [حم م هـ] عن أبي هريرة.\n(حسن) مختصر مسلم ١٨٤٠، السنة ٣٥٦: الطحاوي، حل."],[7230,"«المؤمن الذي يخالط الناس ويصبر على أذاهم أفضل من المؤمن الذي لا يخالط الناس ولا يصبر على أذاهم» .\n(صحيح) [حم خد ت هـ] عن ابن عمر. الصحيحة ٩٣٩."],[7231,"«المؤمن بخير على كل حال تنزع نفسه من بين جنبيه وهو يحمد الله» .\n(صحيح) [ن] عن ابن عباس. الصحيحة ١٦٣٢: حم."],[7232,"«المؤمن غر كريم والفاجر خب لئيم» .\n(حسن) [د ت ك] عن أبي هريرة. الصحيحة ٩٣٥."],[7233,"«المؤمن للمؤمن كالبنيان يشد بعضه بعضا» .\n(صحيح) [ق ت ن] عن أبي موسى. مختصر مسلم ١٧٧٣، تخريج مشكلة الفقر ١٠٤، إيمان ابن أبي شيبة ٩٠."],[7234,"«المؤمن مرآة المؤمن» .\n(صحيح) [طس الضياء] عن أنس. الأحاديث الصحيحة ٩٢٦."],[7235,"«المؤمن مرآة المؤمن والمؤمن أخوالمؤمن يكف عليه ضيعته ويحوطه من ورائه» .\n(حسن) [خد د] عن أبي هريرة. الصحيحة ٩٢٦: ابن وهب في [الجامع] ."],[7236,"«المؤمن مكفر» .\n(صحيح) [ك١] عن سعد. الصحيحة ٢٣٦٧."],[7237,"«المؤمن من أمنه الناس على أموالهم وأنفسهم والمهاجر من هجر الخطايا والذنوب» .\n(صحيح) [هـ] عن فضالة بن عبيد. الصحيحة ٥٤٩: حم، حب، ك."],[7238,"«المؤمن من أهل الإيمان بمنزلة الرأس من الجسد يألم المؤمن لأهل الإيمان كما يألم الجسد لما في الرأس» .\n(حسن) [حم] عن سهل بن سعد. الصحيحة ١١٣٧."],[7239,"«المؤمن يأكل في معى واحد والكافر يأكل في سبعة أمعاء» .\n(صحيح) [حم ق ت هـ] عن ابن عمر ... [حم م] عن جابر: [حم ق] عن أبي هريرة ... [م هـ] عن أبي موسى. مختصر مسلم ١٣١٢."],[7240,"«المؤمن يألف ولا خير فيمن لا يألف ولا يؤلف» .\n(صحيح) [حم] عن سهل بن سعد. الصحيحة ٤٢٦."],[7241,"\"المؤمن يألف ويؤلف ولا خير فيمن لا يألف ولا يؤلف، وخير الناس أنفعهم للناس\".\n(حسن) [قط في الأفراد الضياء] عن جابر. الصحيحة ٤٢٦: طب، هب."],[7242,"(١) في الأصل: [ن، د، ن] وهو خطأ."],[7243,"«المؤمن يشرب في معى واحد والكافر يشرب في سبعة أمعاء» .\n(صحيح) [حم م ت] عن أبي هريرة. مختصر مسلم ١٣١٣."],[7244,"«المؤمن يغار والله أشد غيرا» ١.\n(صحيح) [م] عن أبي هريرة. م ٨/١٠١: حم ٢/٢٣٥و ٣٠١و ٤٣٨٢."],[7245,"«المؤمن يموت بعرق الجبين» .\n(صحيح) [حم ت ن هـ ك] عن بريدة. المشكاة ١٦١٠، أحكام الجنائز ص ٣٥."],[7246,"٢٢٧٧ - «المؤمنون تكافأ دماؤهم وهم يد على من سواهم ويسعى بذمتهم أدناهم ألا لا يقتل مؤمن بكافر ولا ذوعهد في عهده من أحدث حدثا فعلى نفسه ومن أحدث حدثا أو أوى محدثا فعليه لعنة الله والملائكة والناس أجمعين» .\n(صحيح) [د ن ك] عن علي. الإرواء ٢٢٠٩."],[7247,"٢٢٧٨ - «المؤمنون كرجل واحد إن اشتكى رأسه تداعى له سائر الجسد بالحمى والسهر» .\n(صحيح) [حم م] عن النعمان بن بشير. الصحيحة ١١٣٨."],[7248,"«المؤمنون كرجل واحد إن اشتكى رأسه اشتكى كله وإن اشتكى عينه اشتكى كله» .\n(صحيح) [حم م] عن النعمان بن بشير. المصدر نفسه."],[7249,"(١) الأصل: [غيرة] والتصويب من [الجامع] ومصدري الحديث.٢ قلت: وعزاه المناوي لـ[خ] أيضا، وهو خطأ، فليس عنده ٣/٤٥١ الشطر الثاني منه، وقد مضى لفظه برقم ١٩٠١."],[7250,"«المؤمنون هينون لينون كالجمل الأنف إن قيد انقاد وإذا أنيخ على صخرة استناخ» .\n(حسن) [ابن المبارك] عن مكحول مرسلا [هب] عن ابن عمر. الصحيحة ٩٣٦."],[7251,"«الماهر بالقرآن مع السفرة الكرام البررة والذي يقرؤه ويتعتع فيه وهو عليه شاق له أجران» .\n(صحيح) [ق د هـ] عن عائشة."],[7252,"«المتباريان لا يجابان ولا يؤكل طعامهما» .\n(صحيح) [هب] عن أبي هريرة. الصحيحة ٦٢٦."],[7253,"«المتبايعان بالخيار ما لم يتفرقا إلا أن تكون صفقة خيار ولا يحل له أن يفارق صاحبه خشية أن يستقيله» .\n(صحيح) [د ن] عن ابن عمرو. أحاديث البيوع."],[7254,"٢٢٧٩ - «المتبايعان بالخيار ما لم يتفرقا إلا أن يكون البيع كان عن خيار فإن كان البيع عن خيار فقد وجب البيع» .\n(صحيح) [ن] عن ابن عمر. المصدر السابق، الإرواء ١٣١٠/١."],[7255,"٢٢٨٠ - «المتبايعان كل واحد منهما بالخيار على صاحبه ما لم يتفرقا إلا بيع الخيار» .\n(صحيح) [ق د ن] عن ابن عمر. أحاديث البيوع."],[7256,"«المتشبع بما لم يعط كلابس ثوبي زور» .\n(صحيح) [حم ق د] عن أسماء بنت أبي بكر [م] عن عائشة. مختصر مسلم ١٣٨٧، الروض النضير ٨٢٠."],[7257,"«المتمسك بسنتي عند اختلاف أمتي كالقابض على الجمر» .\n(حسن) [الحكيم] عن ابن مسعود. الصحيحة ٩٥٧: الكلاباذي."],[7258,"٢٢٨١ - «المتوفى عنها زوجها لا تلبس المعصفر من الثياب ولا الممشقة ولا الحلي ولا تختضب ولا تكتحل» .\n(صحيح) [م ن] عن أم سلمة. الإرواء ٢١٢٩."],[7259,"«المجالس بالأمانة» ... [خط] عن علي.\n(حسن) الأحاديث الضعيفة ١٩٠٩، ٣٢٢٤: حم، د - جابر. الديلمي - ابن مسعود. ابن المبارك - أبي بكر بن حزم مرسلا."],[7260,"«المجاهد من جاهد نفسه في الله» .\n(صحيح) [ت حب] عن فضالة بن عبيد. الترغيب ٢/١٥٠، الصحيحة ٥٤٩: حم."],[7261,"«المحرمة لا تنتقب ولا تلبس القفازين» .\n(صحيح) [د] عن ابن عمر. خ: المناسك."],[7262,"«المختلعات هن المنافقات» .\n(صحيح) [ت] عن ثوبان. الصحيحة ٦٣٢."],[7263,"«المدعى عليه أولى باليمين إلا أن تقوم عليه البينة» .\n(صحيح) [هق] عن ابن عمرو. الإرواء ٢٦٤١."],[7264,"٢٢٨٣ - «المدينة حرام ما بين عير إلى ثور فمن أحدث فيها حدثا أو أوى فيها محدثا فعليه لعنة الله والملائكة والناس أجمعين لا يقبل الله منه يوم القيامة صرفا ولا عدلا وذمة المسلمين واحدة يسعى بها أدناهم فمن أخفر مسلما فعليه لعنة الله والملائكة والناس أجمعين لا يقبل الله منه يوم القيامة صرفا ولا عدلا ومن ادعى إلى غير أبيه أو انتمى إلى غير مواليه فعليه لعنة الله والملائكة والناس أجمعين لا يقبل الله منه يوم القيامة صرفا ولا عدلا» .\n(صحيح) [حم ق د ت] عن علي [م] عن أبي هريرة. مختصر مسلم ٧٧٧، نقد الكتاني ٤٢، الإرواء ١٠٥٨: الطيالسي، أبو نعيم، هق."],[7265,"٢٢٨٣ - «المدينة حرام ما بين عير إلى ثور لا يختلى خلاها ولا ينفر صيدها ولا تلتقط لقطتها إلا لمن أشاد بها ولا يصلح لرجل أن يحمل فيها سلاحا لقتال ولا يصلح أن يقطع منها شجرة إلا أن يعلف رجل بعيره» .\n(صحيح) [د] عن علي. الإرواء ١٠٥٨: حم."],[7266,"٢٢٨٤ - «المدينة حرام من كذا إلى كذا لا يقطع شجرها ولا يحدث فيها حدث من أحدث فيها حدثا أو أوى محدثا فعليه لعنة الله والملائكة والناس أجمعين لا يقبل الله منه يوم القيامة صرفا ولا عدلا» .\n(صحيح) [حم ق] عن أنس."],[7267,"«المدينة حرم آمن» .\n(صحيح) [أبوعوانة] عن سهل بن حنيف. حم ٣/٤٨٦، م ٤/١١٨."],[7268,"«المراء في القرآن كفر» .\n(صحيح) [د ك] عن أبي هريرة. المشكاة ٣٣٦، الروض النضير ١١٢٤و ١١٢٥."],[7269,"«المرء في صلاة ما انتظرها» .\n(صحيح) [عبد بن حميد] عن جابر. الصحيحة ٢٣٦٨: حم."],[7270,"«المرء مع من أحب» .\n(صحيح) [حم ق ٣] عن أنس [ق] عن ابن مسعود. الروض النضير ١٠٤ - ١٠٦و ٣٦٠و ٣٦١و ٣٧٠و ١٠٢٨ تخريج فقه السيرة ٢١٤."],[7271,"«المرأة عورة فإذا خرجت استشرفها الشيطان» .\n(صحيح) [ت] عن ابن مسعود. المشكاة ٣١٠٩، الإرواء ٢٧٣."],[7272,"«المرأة لآخر أزواجها» .\n(صحيح) [طب] عن أبي الدرداء [خط] عن عائشة. الصحيحة ١٢٨١، الترغيب ١/١٣٦: ابن خزيمة، ابن حبان."],[7273,"٢٢٨٥ - «المزدلفة كلها موقف» ... [ن] عن جابر.\n(صحيح) حجة النبي صلى الله عليه وآله وسلم: ص ٧٦؛ حم، د، الدارمي، هـ، ابن الجارود، ك."],[7274,"«المزر١ كله حرام.... ...» .\n(صحيح) [طب] عن ابن عباس. الضعيفة ٤٦٧٥."],[7275,"٢٢٨٦ - «المسألة أن ترفع يديك حذو منكبيك والاستغفار أن تشير بأصبع واحدة والابتهال تمد يديك جميعا» .\n(صحيح) [د] عن ابن عباس. صحيح أبي داود ١٣٣٨ - ١٣٤٠: الضياء."],[7276,"«المسائل كدوح يكدح بها الرجل وجهه فمن شاء أبقى على وجهه ومن شاء ترك إلا أن يسأل الرجل ذا سلطان أو في أمر لا يجد منه بدا» .\n(صحيح) [حم د حب] عن سمرة. صحيح الترغيب ٧٨٧."],[7277,"«المستبان شيطانان يتهاتران ويتكاذبان» .\n(صحيح) [حم خد] عن عياض بن حمار. إيمان أبي عبيد ١١١."],[7278,"«المستبان ما قالا فعلى البادئ منهما حتى يعتدي المظلوم» .\n(صحيح) [حم م د ت] عن أبي هريرة. مختصر مسلم ١٨١٢."],[7279,"٢٢٨٧ - «المستحاضة تدع الصلاة أيام أقرائها ثم تغتسل وتصلي والوضوء عند كل صلاة» .\n(صحيح) [٤] عن دينار. صحيح أبي داود ٣١١، الإرواء ٢٠٧."],[7280,"(١) نبيذ يتخذ من ذرة وشعير."],[7281,"«المستحاضة تغتسل من قرء إلى قرء» .\n(صحيح) [طس] عن ابن عمرو. الروض النضير ٥٩٠: طص."],[7282,"«المستشار مؤتمن» .\n(صحيح) [٤] عن أبي هريرة [ت] عن أم سلمة [هـ] عن ابن مسعود. الصحيحة ١٦٤١: خد، الطحاوي، ك، هب - أبي هريرة. حم، الدارمي، حب - أبي مسعود الأنصاري. حم في [الزهد]، الطحاوي - أبي سلمة بن عبد الرحمن مرسلا."],[7283,"«المسجد الذي أسس على التقوى مسجدي هذا» .\n(صحيح) [م ت] عن أبي سعيد [حم ك] عن أبي. حب ١٠٣٧ - سهل."],[7284,"«المسجد بيت كل مؤمن» .\n(حسن) [حل] عن سلمان. الصحيحة ٧١٦: القضاعي."],[7285,"«المسك أطيب الطيب» .\n(صحيح) [م ت] عن أبي سعيد."],[7286,"«المسلم أخو المسلم» ... [د] عن سويد بن حنظلة.\n(صحيح) الصحيحة ٥٠٤: م، ت - أبي هريرة. حم، ق، د، ت - ابن عمر."],[7287,"«المسلم أخو المسلم ولا يحل لمسلم باع من أخيه بيعا فيه عيب إلا بينه له» .\n(صحيح) [حم هـ ك] عن عقبة بن عامر. الإرواء ١٣٢١، أحاديث البيوع."],[7288,"٢٢٨٨ - «المسلم أخو المسلم لا يخونه ولا يكذبه ولا يخذله كل المسلم على المسلم حرام عرضه وماله ودمه التقوى هاهنا - وأشار إلى القلب - بحسب امرئ من الشر أن يحقر أخاه المسلم» .\n(صحيح) [ت] عن أبي هريرة. الإرواء ٢٤٥٠\" م١."],[7289,"(١) وسيأتي لفظه في [لا تحاسدوا.. ...] برقم ٧٢٤٢."],[7290,"«المسلم أخوالمسلم لا يظلمه ولا يسلمه ومن كان في حاجة أخيه كان الله في حاجته ومن فرج عن مسلم كربة فرج الله عنه بها كربة من كرب يوم القيامة ومن ستر مسلما ستره الله يوم القيامة» .\n(صحيح) [حم ق ٣] عن ابن عمر. مختصر مسلم ١٨٣٠، الصحيحة ٥٠٤، الإرواء ٢٤٥٠."],[7291,"٢٢٨٩ - «المسلم إذا سئل في القبر يشهد أن لا إله إلا الله وأن محمدا رسول الله فذلك قوله تعالى: ﴿يُثَبِّتُ اللَّهُ الَّذِينَ آمَنُوا بِالْقَوْلِ الثَّابِتِ فِي الْحَيَاةِ الدُّنْيَا وَفِي الْآخِرَةِ﴾» .\n(صحيح) [حم ق ٤] عن البراء."],[7292,"«المسلم من سلم المسلمون من لسانه ويده» ... [م] عن جابر.\n(صحيح) الروض النضير ٢٠٢: ٥٩١: الطيالسي، حم، طص. الطيالسي، حم، خ، د، ن، الدارمي - ابن عمرو."],[7293,"«المسلم من سلم المسلمون من لسانه ويده والمؤمن من أمنه الناس على دمائهم وأموالهم» .\n(صحيح) [حم ت ن ك حب] عن أبي هريرة [طب] عن واثلة. المشكاة ٣٣."],[7294,"«المسلم من سلم المسلمون من لسانه ويده والمهاجر من هجر ما نهى الله عنه» .\n(صحيح) [خ د ن] عن ابن عمرو. الروض النضير: ٥٩١ الطيالسي؛ حم، الدارمي."],[7295,"٢٢٩٠ - «المسلمون تتكافأ دماؤهم يسعى بذمتهم أدناهم ويجير عليهم أقصاهم وهم يد على من سواهم يرد مشدهم على مضعفهم ومسرعهم على قاعدهم لا يقتل مؤمن بكافر ولا ذوعهد في عهده» .\n(حسن) [د هـ] عن ابن عمرو. الإرواء ٢٢٠٨."],[7296,"«المسلمون شركاء في ثلاثة: في الكلأ والماء والنار» .\n(صحيح) [حم د] عن رجل. الإرواء ١٥٥٢."],[7297,"«المسلمون على شروطهم» .\n(صحيح) [د ك] عن أبي هريرة. الإرواء ١٣٠٣."],[7298,"«المسلمون عند شروطهم فيما أحل» .\n(صحيح) [طب] عن رافع بن خديج. المصدر نفسه."],[7299,"«المسلمون عند شروطهم ما وافق الحق من ذلك» .\n(صحيح) [ك] عن أنس وعن عائشة. المصدر نفسه."],[7300,"«المصائب والأمراض والأحزان في الدنيا جزاء» .\n(صحيح) [ص حل] عن مسروق مرسلا. الضعيفة ٢٩٢٤."],[7301,"«المطلقة ثلاثا ليس لها سكنى ولا نفقة» .\n(صحيح) [ن] عن فاطمة بنت قيس. الروض النضير ٨٣٦: حم، م."],[7302,"«المعتدي في الصدقة كمانعها» ... [حم د ت هـ] عن أنس.\n(صحيح) المشكاة ١٨٠١، صحيح الترغيب ٧٨٣: ابن خزيمة."],[7303,"«المغرب وتر النهار فأوتروا صلاة الليل» .\n(صحيح) [طب] عن ابن عمر. السنة ٧٨٤، الروض النضير ٥٢٣: حم، طس، حل."],[7304,"«المقام المحمود الشفاعة» ... [حل هب] عن أبي هريرة.\n(صحيح) الصحيحة ٢٣٦٩: حم، ت، الدولابي، الطحاوي، تمام، ابن أبي عاصم."],[7305,"«المكاتب عبد ما بقي عليه من كتابته درهم» .\n(حسن) [د هق] عن ابن عمرو. الإرواء ١٦٧٤."],[7306,"٢٢٩١ - «المكاتب يعتق بقدر ما أدى ويقام عليه الحد بقدر ما عتق منه ويرث بقدر ما عتق منه» .\n(صحيح) [ن] عن ابن عباس. الإرواء ١٧٢٦: ت، هق، الضياء."],[7307,"«المكثرون هم الأسفلون يوم القيامة» .\n(صحيح) [الطيالسي] عن أبي ذر. الصحيحة ١٧٦٨."],[7308,"«المكر والخديعة في النار» .\n(صحيح) [هب] عن قيس بن سعد. الصحيحة ١٠٥٧."],[7309,"«المكر والخديعة والخيانة في النار» .\n(حسن) [د في مراسيله] عن الحسن مرسلا. الصحيحة ١٠٥٧: عق، عد، أبو نعيم - أبي هريرة."],[7310,"٢٢٩٢ - «الملائكة تصلي على أحدكم ما دام في مصلاه الذي صلى فيه ما لم يحدث أو يقم: اللهم اغفر له اللهم ارحمه» .\n(صحيح) [حم د ن] عن أبي هريرة. صحيح أبي داود ٤٨٨: ق."],[7311,"«الملائكة شهداء الله في السماء وأنتم شهداء الله في الأرض» .\n(صحيح) [ن] عن أبي هريرة. أحكام الجنائز ٤٤ - ٤٥: حم."],[7312,"«الملك في قريش والقضاء في الأنصار والأذان في الحبشة والأمانة في الأزد» .\n(صحيح) [حم ت] عن أبي هريرة. الصحيحة ١٠٨٣."],[7313,"«المنتعل بمنزلة الراكب» .\n(صحيح) [سمويه] عن جابر. الصحيحة ٣٤٥: حم، م، د١."],[7314,"«المنتعل راكب» .\n(صحيح) [ابن عساكر] عن أنس. الصحيحة ٣٤٥: أبو الشيخ، أبو نعيم، ابن عساكر."],[7315,"(١) قلت: وقد مضى لفظهم برقم ٩٥٤."],[7316,"«المنحة مردودة والناس على شروطهم ما وافق الحق» .\n(صحيح) [البزار] عن أنس. الصحيحة ٦١٠و ٦١١، الإرواء ١٣٠٣."],[7317,"٢٢٩٣ - «المنفق على الخيل في سبيل الله كباسط يديه بالصدقة لا يقبضها» .\n(صحيح) [حم د ك] عن ابن الحنظلية. الترغيب ٢/١٦١."],[7318,"«المهدي من عترتي من ولد فاطمة» .\n(صحيح) [د هـ ك] عن أم سلمة. الضعيفة ٨٠، الروض النضير ٢/٥٤."],[7319,"«المهدي منا أهل البيت يصلحه الله في ليلة» .\n(صحيح) [حم هـ] عن علي. الروض النضير ٢/٥٣، الصحيحة ٢٣٧١، عق، عد، حل."],[7320,"«المهدي مني أجلى الجبهة أقنى الأنف يملأ الأرض قسطا وعدلا كما ملئت جورا وظلما يملك سبع سنين» .\n(حسن) [د ك] عن أبي سعيد. الروض النضير ٢/٥٣، المشكاة ٥٤٥٤."],[7321,"«الميزان بيد الرحمن يرفع أقواما ويضع آخرين» .\n(صحيح) [البزار] عن نعيم بن همار. السنة ٤٥٠ - ٤٥٣: ابن أبي عاصم، الآجري، ك - النواس بن سمعان. ابن أبي عاصم، الآجري - سبرة."],[7322,"«الميت من ذات الجنب شهيد» .\n(صحيح) [حم طب] عن عقبة بن عامر. أحكام الجنائز ٤٠، الصحيحة ٢٣٧٢."],[7323,"«الميت يبعث في ثيابه التي يموت فيها» .\n(صحيح) [د حب ك] عن أبي سعيد. المشكاة ١٦٤٠، الصحيحة ١٦٧١: هق."],[7324,"\"الميت يعذب ببكاء الحي إذا قالوا: وا عضداه! وا كاسياه! وا ناصراه! وا جبلاه! ونحو هذا يتعتع ويقال أنت كذلك؟! أنت كذلك؟! \".\n(حسن) [حم هـ] عن أبي موسى. الترغيب ٤/١٧٦."],[7325,"«الميت يعذب في قبره بما نيح عليه» .\n(صحيح) [حم ق ن هـ] عن عمر. أحكام الجنائز ٢٨."],[7326,"حرف النون."],[7327,"٢٢٩٤ - «ناركم هذه التي توقد بنوآدم جزء من سبعين جزءا من نار جهنم قيل: يا رسول الله! إن كانت لكافية؟ قال: فإنها فضلت عليها بتسعة وستين جزءا كلهن مثل حرها» .\n(صحيح) [حم ق ت] عن أبي هريرة. مختصر مسلم ١٩٧٦."],[7328,"«ناركم هذه جزء من سبعين جزءا من نار جهنم لكل جزء منها حرها» .\n(صحيح) [ت] عن أبي سعيد. الترغيب ٤/٢٢٦."],[7329,"٢٢٩٥ - «ناس من أمتي عرضوا علي غزاة في سبيل الله يركبون ثبج هذا البحر ملوكا على الأسرة» .\n(صحيح) [ق ت ن] عن أنس [حم م ن هـ] عن أم حرام. مختصر مسلم ١٠٧٤، خ: جهاد - أم حرام١."],[7330,"«نبدأ بما بدأ الله به» .\n(صحيح) [حم ٣] عن جابر. الإرواء ١١٢٠: م."],[7331,"«نجا أول هذه الأمة باليقين والزهد ويهلك آخرها بالبخل والأمل» .\n(حسن) [ابن أبي الدنيا] عن ابن عمرو. المشكاة ٥٢٨١."],[7332,"(١) قلت: ومضى لفظه في: [عجبت من قوم.. ...] رقم ٣٩٨٧."],[7333,"«نح الأذى عن طريق المسلمين» .\n(صحيح) [ع حب] عن أبي برزة. الصحيحة ٢٣٧٣: ابن أبي شيبة، الضياء."],[7334,"٢٢٩٦ - «نحرت هاهنا ومنى كلها منحر فانحروا في رحالكم ووقفت هاهنا وعرفة كلها موقف ووقفت هاهنا وجمع كلها موقف» .\n(صحيح) [م د] عن جابر. حجة النبي صلى الله عليه وآله وسلم ص ٧٤، ٨٦."],[7335,"٢٢٩٧ - «نحن آخر الأمم وأول من يحاسب يقال: أين الأمة الأمية ونبيها؟ فنحن الآخرون الأولون» .\n(صحيح) [هـ] عن ابن عباس. الصحيحة ٢٣٧٤."],[7336,"٢٢٩٨ - «نحن أحق بالشك من إبراهيم إذ قال: ﴿رَبِّ أَرِنِي كَيْفَ تُحْيِي الْمَوْتَى قَالَ أولَمْ تُؤْمِنْ قَالَ بَلَى وَلَكِنْ لِيَطْمَئِنَّ قَلْبِي﴾ ويرحم الله لوطا لقد كان يأوي إلى ركن شديد ولو لبثت في السجن طول ما لبث يوسف لأجبت الداعي» .\n(صحيح) [حم ق هـ] عن أبي هريرة. مختصر مسلم ١٦٠٨، الصحيحة ١٨٦٧."],[7337,"٢٢٩٩ - «نحن أحق وأولى بموسى منكم» .\n(صحيح) [حم ق د هـ] عن ابن عباس. المشكاة ٢٠٦٧."],[7338,"٢٣٠٠ - «نحن الآخرون السابقون يوم القيامة بيد أنهم أوتوا الكتاب من قبلنا وأوتيناه من بعدهم ثم هذا يومهم الذي فرض الله عليهم فاختلفوا فيه فهدانا الله له فالناس لنا فيه تبع اليهود غدا والنصارى بعد غد» .\n(صحيح) [حم ق ن] عن أبي هريرة."],[7339,"٢٣٠١ - «نحن بنوالنضر بن كنانة لا نقفوأمنا ولا ننتفي من أبينا» .\n(صحيح) [حم هـ] عن الأشعث بن قيس. الصحيحة ٣٣٧٥: تخ، ابن سعد، ابن منده، خط، ابن سعد - الزهري مرسلا."],[7340,"٢٣٠٢ - «نحن نازلون غدا بخيف بني كنانة حيث قاسمت قريش على الكفر» .\n(صحيح) [هـ] عن أسامة بن زيد. مختصر مسلم ٧٤٩ - أبي هريرة."],[7341,"٢٣٠٣ - «نزع رجل لم يعمل خيرا قط غصن شوك عن الطريق إما كان في شجرة مقطعة فألقاه وإما كان موضوعا فأماطه فشكر الله له بها فأدخله الجنة» .\n(حسن) [د حب] عن أبي هريرة. الترغيب ٤/٣٦."],[7342,"«نزل الحجر الأسود من الجنة وهو أشد بياضا من اللبن فسودته خطايا بني آدم» .\n(صحيح) [ت] عن ابن عباس. المكشاة ٢٥٧٧، الترغيب ٢/١٢٣."],[7343,"٢٣٠٤ - «نزل جبريل فأمني فصليت معه ثم صليت معه ثم صليت معه ثم صليت معه ثم صليت معه ثم قال: بهذا أمرت» .\n(صحيح) [ق د ن هـ] عن أبي مسعود. صحيح أبي داود ٤١٧."],[7344,"٢٣٠٥ - «نزل ملك من السماء فكذبه بما قال لك فلما انتصرت وقع الشيطان فلم أكن لأجلس إذا وقع الشيطان» .\n(حسن) [د] عن أبي هريرة. الصحيحة ٢٣٧٦."],[7345,"٢٣٠٦ - \"نزل نبي من الأنبياء تحت شجرة فلدغته نملة فأمر بجهازه فأخرج من تحتها ثم أمر ببيتها فأحرق بالنار فأوحى الله إليه: فهلا نملة واحدة [...] حم خ د ن\" عن أبي هريرة.\n(صحيح) حم ٢/٣١٣/٥٤٩، خ ٢/٣٢٩: مختصر مسلم ١٥٠٢."],[7346,"٢٣٠٧ - «نزلت هذه الآية في أهل قباء: ﴿فِيهِ رِجَالٌ يُحِبُّونَ أَنْ يَتَطَهَّرُوا وَاللَّهُ يُحِبُّ الْمُطَّهِّرِينَ﴾» ... [ت] عن أبي هريرة. الإرواء ٤٥، صحيح أبي داود ٣٤: د، هـ، ة ق. حم، ابن خزيمة - عويم بن ساعدة.\n(صحيح) ك، هق - ابن عباس."],[7347,"«نصبر ولا نعاقب» .\n(صحيح) [عم] عن أبي. الصحيحة ٢٣٧٦."],[7348,"«نصرت بالصبا وأهلكت عاد بالدبور» .\n(صحيح) [حم ق] عن ابن عباس. مختصر مسلم ٤٥٠، الروض النضير ١٢٦."],[7349,"«نضر الله امرءا سمع منا حديثا فحفظه حتى يبلغه غيره فرب حامل فقه إلى من هوأفقه ورب حامل فقه ليس بفقيه» .\n(صحيح) [ت الضياء] عن زيد بن ثابت. الروض النضير ٢٧٦، الصحيحة ٤٠٣: حب."],[7350,"«نضر الله امرءا سمع منا شيئا فبلغه كما سمعه فرب مبلغ أوعى من سامع» .\n(صحيح) [حم ت حب] عن ابن مسعود. صحيح الترغيب ٨٤."],[7351,"٢٣٠٨ - «نضر الله عبدا سمع مقالتي فوعاها ثم بلغها عني فرب حامل فقه غير فقيه ورب حامل فقه إلى من هو أفقه منه» .\n(صحيح) [حم هـ] عن أنس. المصدر نفسه."],[7352,"٢٣٠٩ - \"نضر الله عبدا سمع مقالتي فوعاها وحفظها ثم أداها إلى من لم يسمعها فرب حامل فقه غير فقيه ورب حامل فقه إلى من هوأفقه منه ثلاث لا يغل عليهن قلب امرئ مسلم: إخلاص العمل لله، والنصح لأئمة المسلمين ولزوم جماعتهم فإن دعوتهم تحوط من وراءهم\".\n(صحيح) [حم هـ ك] عن جبير بن مطعم [د هـ] عن زيد بن ثابت [ت هـ] عن ابن مسعود. المصدر نفسه."],[7353,"«نطفة الرجل بيضاء غليظة ونطفة المرأة صفراء رقيقة فأيهما غلبت صاحبتها فالشبه له،....... ...» .\n(صحيح) [أبوالشيخ في] العظمة\"\" عن ابن عباس. الضعيفة ٤٦٨٩."],[7354,"«نعم الإدام الخل» ... [حم م ٤] عن جابر [م ت] عن عائشة.\n(صحيح) الصحيحة ٢٢٢٠: الدارمي - جابر. مختصر مسلم ١٣١٥."],[7355,"«نعم الجهاد الحج» .\n(صحيح) [خ] عن عائشة."],[7356,"٢٣١٠ - «نعم الرجل أبو بكر نعم الرجل عمر نعم الرجل أبو عبيدة بن الجراح نعم الرجل أسيد بن حضير نعم الرجل ثابت بن قيس بن شماس نعم الرجل معاذ بن جبل نعم الرجل معاذ بن عمروبن الجموح نعم الرجل سهيل بن بيضاء» .\n(صحيح) [تخ ت ك] عن أبي هريرة. الصحيحة ٨٧٥: حم، د، حب."],[7357,"٢٣١١ - «نعم الرجل عبد الله لوكان يصلي من الليل» .\n(صحيح) [حم ق] عن حفصة."],[7358,"«نعم السحور التمر» ... [حل] عن جابر.\n(صحيح) الصحيحة ٥٦٢، صحيح الترغيب ١٠٦٤: حب، هق - أبي هريرة."],[7359,"٢٣١٢ - «نعم السورتان هما يقرآن في الركعتين قبل الفجر: ﴿قُلْ يَا أَيُّهَا الْكَافِرُونَ﴾ و﴿قُلْ هُوَ اللَّهُ أَحَدٌ﴾» .\n(صحيح) [حب هب] عن عائشة. الصحيحة ٦٤٦."],[7360,"٢٣١٣ - «نعم الصدقة اللقحة الصفي منحة والشاة الصفية منحة يغدو بإناء ويروح بإناء» .\n(صحيح) [مالك خ] عن أبي هريرة."],[7361,"«نعم الميتة أن يموت الرجل دون حقه» .\n(صحيح) [حم] عن سعد. الصحيحة ٦٩٧."],[7362,"«نعم عبد الله خالد بن الوليد سيف من سيوف الله» .\n(صحيح) [حم ت] عن أبي هريرة. الصحيحة ١٢٣٧."],[7363,"٢٣١٤ - «نعما لمملوك أن يتوفى يحسن عبادة ربه وينصح لسيده نعما له» .\n(صحيح) [ق ت] عن أبي هريرة."],[7364,"«نعمتان مغبون فيهما كثير من الناس: الصحة والفراغ» .\n(صحيح) [خ ت هـ] عن ابن عباس. ك ٤/٣٠٦."],[7365,"«نفس المؤمن معلقة بدينه حتى يقضى عنه» .\n(صحيح) [حم ت هـ ك] عن أبي هريرة. المشكاة ٢٩١٥."],[7366,"«نفقة الرجل على أهله صدقة» .\n(صحيح) [خ ت] عن ابن مسعود. الصحيحة ٩٨٢."],[7367,"«نفي بعهدهم ونستعين الله عليهم» .\n(صحيح) [م] عن حذيفة. الصحيحة ٢١٦١: حم، الطحاوي، ك."],[7368,"«نهران من الجنة: النيل والفرات» .\n(صحيح) [الشيرازي] عن أبي هريرة. الصحيحة ١١١: حم، ع، خط."],[7369,"«نهيت أن أمشي عريانا» .\n(صحيح) [طب] عن ابن عباس. الصحيحة ٢٣٧٨."],[7370,"«نهيت عن التعري» .\n(صحيح) [الطيالسي] عن ابن عباس. الصحيحة ٢٣٧٨: ك، حم، ك - أبي الطفيل."],[7371,"«نهيت عن المصلين» .\n(صحيح) [طب] عن أنس. الصحيحة ٢٣٧٩."],[7372,"٢٣١٥ - «نهيتكم عن الظروف وإن الظروف لا تحل شيئا ولا تحرمه وكل مسكر حرام» .\n(صحيح) [م] عن بريدة. مختصر مسلم ١٢٧٤."],[7373,"٢٣١٦ - «نهيتكم عن النبيذ إلا في سقاء فاشربوا في الأسقية كلها ولا تشربوا مسكرا» .\n(صحيح) [م] عن بريدة. م ٣/٦٥و ٦/٨٢و ٩٨."],[7374,"٢٣١٧ - «نهيتكم عن ثلاث وأنا آمركم بهن نهيتكم عن زيارة القبور فزوروها فإن في زيارتها تذكرة ونهيتكم عن الأشربة أن لا تشربوا إلا في ظروف الأدم فاشربوا في كل وعاء غير أن لا تشربوا مسكرا ونهيتكم عن لحوم الأضاحي أن تأكلوها بعد ثلاث فكلوا واستمتعوا بها في أسفاركم» .\n(صحيح) [د] عن بريدة. أحكام الجنائز ص ١٧٩ - ١٧٩."],[7375,"«نهيتكم عن زيارة القبور فزوروها فإن لكم فيها عبرة» .\n(صحيح) [طب] عن أم سلمة. أحكام الجنائز ص ١٧٩: حم، ك، هق - أبي سعيد."],[7376,"«نهيتكم عن زيارة القبور فزوروها فإنها تذكركم الموت» .\n(صحيح) [ك] عن أنس. أحكام الجنائز ص ١٨٠: حم."],[7377,"«نهينا عن الكلام في الصلاة إلا بالقرآن والذكر» .\n(صحيح) [طب] عن ابن مسعود. الصحيحة ٢٣٨٠: ن."],[7378,"فصل في المحلى بـ\"ال\" من هذا الحرف."],[7379,"«النائحة إذا لم تتب قبل موتها تقام يوم القيامة وعليها سربال من قطران ودرع من جرب» ١.\n(صحيح) [حم م] عن أبي مالك الأشعري. الصحيحة ١٩٥٢."],[7380,"«النار جبار» .\n(صحيح) [د هـ] عن أبي هريرة. الصحيحة ٢٣٨١: ن. عد - أنس."],[7381,"«النار عدو فاحذروها» .\n(صحيح) [حم م] عن ابن عمر. حم ٢/٩٠. حم ٤/٣٩٩، ق - أبي موسى٢."],[7382,"«الناس تبع لقريش في الخير والشر» .\n(صحيح) [حم م] عن جابر. الصحيحة ١٠٠٦."],[7383,"٢٣١٨ - «الناس معادن خيارهم في الجاهلية خيارهم في الإسلام إذا فقهوا الناس تبع لقريش في هذا الشأن مسلمهم تبع لمسلمهم وكافرهم تبع لكافرهم تجدون من خير الناس أشد الناس كراهية لهذا الشأن حتى يقع فيه» .\n(صحيح) [ق] عن أبي هريرة."],[7384,"٢٣١٩ - \"الناس معادن كمعادن الذهب والفضة، خيارهم في الجاهلية خيارهم في الإسلام إذا فقهوا والأرواح جنود مجندة فما تعارف منها ائتلف وما تناكر منها اختلف\".\n(صحيح) [م] عن أبي هريرة. مختصر مسلم ١٧٧٢: حم ٢/٥٣٩."],[7385,"(١) قلت: وفي رواية [حم]: [ثم يغلى عليها درع من لهب النار] وسيأتي بهذا اللفظ من رواية [هـ] عن ابن عباس قبيل باب المناهي.٢ قلت: ومضى لفظه برقم ٢٦٦٩."],[7386,"«الناس ولد آدم وآدم من تراب» .\n(حسن) [ابن سعد] عن أبي هريرة. الصحيحة ١٠٠٩."],[7387,"«النبي لا يورث» .\n(صحيح) [ع] عن حذيفة. ق - أبي بكر الصديق١."],[7388,"«النجوم أمنة للسماء فإذا ذهبت النجوم أتى السماء ما توعد وأنا أمنة لأصحابي فإذا ذهبت أتى أصحابي ما يوعدون وأصحابي أمنة لأمتي فإذا ذهب أصحابي أتى أمتي ما يوعدون» .\n(صحيح) [حم م] عن أبي موسى. مختصر مسلم ١٧٤١، الروض النضير ٨٧٥."],[7389,"٢٣٢٠ - «النخاعة في المسجد خطيئة وكفارتها دفنها» .\n(صحيح) [حم ق] عن أنس. صحيح أبي داود ٤٩٥."],[7390,"«الندم توبة» .\n(صحيح) [حم تخ هـ ك] عن ابن مسعود [ك هب] عن أنس. الروض النضير ٦٤٢و ١١٥٠."],[7391,"«الندم توبة والتائب من الذنب كمن لا ذنب له» .\n(حسن) [طب حل] عن أبي سعيد الأنصاري. الضعيفة ٦١٥و ٦١٦."],[7392,"«النذر نذران فما كان من نذر في طاعة الله فذلك لله وفيه الوفاء وما كان من نذر في معصية الله فذلك للشيطان ولا وفاء فيه ويكفره ما يكفر اليمين» .\n(صحيح) [ن] عن عمران بن حصين. الصحيحة ٤٧٩."],[7393,"(١) قلت: وسيأتي حديثه بلفظ: [لا نورث. ...] برقم ٧٥٦٠."],[7394,"«النذر ... كفارته كفارة يمين» .\n(صحيح) [طب] عن عقبة بن عامر. الإرواء ٢٥٨٦."],[7395,"«النصر مع الصبر والفرج مع الكرب: وإن مع العسر يسرا» ... [خط] عن أنس.\n(صحيح) الصحيحة ٢٣٨٢: حم، عبد بن حميد، ك، حل، الضياء - ابن عباس."],[7396,"٢٣٢١ - «النكاح سنتي فمن لم يعمل بسنتي فليس مني وتزوجوا فإني مكاثر بكم الأمم يوم القيامة ومن كان ذا طول فلينكح ومن لم يجد فعليه بالصيام فإن الصوم له وجاء» .\n(صحيح) [هـ] عن عائشة. الصحيحة ٢٣٨٣."],[7397,"«النوم أخو الموت ولا يموت أهل الجنة» .\n(صحيح) [هب] عن جابر. الصحيحة ١٠٨٦."],[7398,"٢٣٢٢ - «النياحة على الميت من أمر الجاهلية وإن النائحة إذا لم تتب قبل أن تموت فإنها تبعث يوم القيامة عليها سرابيل من قطران ثم يغلى عليها بدروع من لهب النار» .\n(صحيح) [هـ] عن ابن عباس. الترغيب ٤/١٧٧: حم، م - أبي مالك الأشعري١."],[7399,"(١) مضى حديثه مفرقا برقمي ٨٨٣و ٦٧٩٢."],[7400,"باب المناهي."],[7401,"«نهى رسول الله صلى الله عليه وآله وسلم أن تتبع جنازة معها رانة» .\n(حسن) [هـ] عن ابن عمر. أحكام الجنائز ٧٠."],[7402,"«نهى أن تستتر الجدر» .\n(حسن) [هق] عن علي بن الحسين مرسلا. الصحيحة ٢٣٨٤."],[7403,"«نهى أن تصبر البهائم» .\n(صحيح) [ق د ن هـ] عن أنس. مختصر مسلم ١٢٤٧."],[7404,"«نهى أن تكلم النساء إلا بإذن أزواجهن» .\n(صحيح) [طب] عن عمرو. الصحيحة ٦٥٢."],[7405,"[نهى أن يبال بأبواب المساجد ...] . (.... ...) [د في مراسيله] عن مكحول مرسلا\"."],[7406,"«نهى أن يبال في الماء الراكد» .\n(صحيح) [م ن هـ] عن جابر. صحيح الترغيب ١٤٧."],[7407,"«نهى أن يبول الرجل في مستحمه» .\n(صحيح) [ت] عن عبد الله بن مغفل. المشكاة ٣٥٣، صحيح أبي داود ٢١: د، ن، ك، هق - أبي هريرة."],[7408,"«نهى أن يتباهى الناس في المساجد» .\n(صحيح) [حب] عن أنس. صحيح أبي داود ٤٧٥."],[7409,"«نهى أن يتخذ شيء فيه الروح غرضا» .\n(صحيح) [حم ت ن] عن ابن عباس. غاية المرام ٣٨٢: م."],[7410,"«نهى أن يتزعفر الرجل» .\n(صحيح) [ق ٣] عن أنس. مختصر مسلم ١٣٤٦."],[7411,"«نهى أن يتعاطى السيف مسلولا» .\n(صحيح) [حم د ت ك] عن جابر. المشكاة ٣٥٢٧."],[7412,"«نهى أن يتنفس في الإناء أو ينفخ فيه» .\n(صحيح) [حم د ت هـ] عن ابن عباس. الإرواء ٢٠٣٧."],[7413,"«نهى أن يجلس الرجل بين الرجلين إلا بإذنهما» .\n(حسن) [هق] عن ابن عمرو. الصحيحة ٢٣٨٥: ابن منده."],[7414,"«نهى أن يجلس الرجل في الصلاة وهو معتمد على يده اليسرى وقال: إنها صلاة اليهود» .\n(صحيح) [ك هق] عن ابن عمر. المشكاة ٩١٤، الإرواء ٣٨٠."],[7415,"«نهى أن يجلس بين الضح والظل وقال: مجلس الشيطان» .\n(صحيح) [حم] عن رجل. الصحيحة ٨٣٨."],[7416,"«نهى أن يجمع أحد بين اسمه وكنيته» .\n(صحيح) [ت] عن أبي هريرة. المشكاة ٤٧٦٩."],[7417,"«نهى أن يسافر بالقرآن إلى أرض العدو» .\n(صحيح) [ق د هـ] عن ابن عمر. الإرواء ١٣٠٠و ٢٥٥٨."],[7418,"«نهى أن يستنجي أحد بعظم أو روثة أو حممة» .\n(صحيح) [د قط هق] عن ابن مسعود. صحيح أبي داود ٢٩: البزار - عبد الله بن الحارث بن جزء."],[7419,"«نهى أن يستنجي ببعرة أو عظم» .\n(صحيح) [حم م د] عن جابر."],[7420,"«نهى أن يسمى أربعة أسماء: أفلح ويسارا ونافعا ورباحا» .\n(صحيح) [د هـ] عن سمرة. الترغيب ٣/٨٥."],[7421,"«نهى أن يشرب الرجل قائما» ... [م د ت] عن أنس.\n(صحيح) الصحيحة ١٧٧: الطيالسي، حم، الدارمي، هـ، الطحاوي، ع - الضياء."],[7422,"«نهى أن يصلي الرجل في لحاف لا يتوشح به ونهى أن يصلي الرجل في سراويل وليس عليه رداء» .\n(حسن) [د ك] عن بريدة. صحيح أبي داود ٦٤٦."],[7423,"«نهى أن يصلي الرجل ورأسه معقوص» ... [طب] عن أم سلمة.\n(صحيح) الأحاديث الصحيحة ٢٣٨٦: حم، الدارمي، هـ - أبي رافع."],[7424,"«نهى أن يصلي الرجل وهو حاقن» .\n(صحيح) [هـ] عن أبي أمامة. ضعيف أبي داود ١١و ١٢: حم."],[7425,"«نهى أن يصلي خلف المتحدث والنائم» .\n(حسن) [هـ] عن ابن عباس. الإرواء ٣٧٥."],[7426,"«نهى أن يصلي على الجنائز بين القبور» .\n(صحيح) [طس] عن أنس. أحكام الجنائز ٦/١٠."],[7427,"«نهى أن يضع الرجل إحدى رجليه على الأخرى وهو مستلق على ظهره» .\n(صحيح) [حم] عن أبي سعيد. الصحيحة ١٢٥٥: حم، م، ت، الطحاوي - جابر. الطحاوي، حب - أبي هريرة."],[7428,"«نهى أن يطرق الرجل أهله ليلا» .\n(صحيح) [ق] عن جابر. مختصر مسلم ١١١٨."],[7429,"«نهى أن يفرد يوم الجمعة بصوم» .\n(صحيح) [حم] عن أبي هريرة. م ٣/١٥٤."],[7430,"«نهى أن يقام الرجل من مقعده ويجلس فيه آخر» ١.\n(صحيح) [خ] عن ابن عمر. خ الاستئذان٢."],[7431,"«نهى أن يقتل شيء من الدواب صبرا» .\n(صحيح) [حم م هـ] عن جابر. حم ٣/٢١٨، ٣٢٢، ٣٣٩، م ٦/٧٣."],[7432,"«نهى أن يقعد الرجل بين الظل والشمس» .\n(صحيح) [ك] عن أبي هريرة [هـ] عن بريدة. الصحيحة ٨٣٨."],[7433,"«نهى أن يقعد على القبر وأن يجصص أو يبنى عليه» .\n(صحيح) [حم د ن] عن جابر. أحكام الجنائز ٢٠٤، الإرواء ٧٥٧."],[7434,"«نهى أن يقوم الإمام فوق شيء والناس خلفه» .\n(صحيح) [د ك] عن حذيفة. المشكاة ١٦٩٢، صحيح أبي داود ٦١٠، ٦١١."],[7435,"«نهى أن يكتب على القبر شيء» .\n(صحيح) [هـ ك] عن جابر. أحكام الجنائز ٢٠٤: د، ن."],[7436,"«نهى أن يمس الرجل ذكره بيمينه وأن يمشي في نعل واحدة وأن يشتمل الصماء وأن يحتبي في ثوب ليس على فرجه منه شيء» .\n(صحيح) [ن] عن جابر٣."],[7437,"(١) قلت: فيه إشعار لطيف بأن النهي يتحقق ولو جلس في المقعد غير المقيم، وهو الذي جزم به القرطبي وتبعه المناوي، والناس عن هذا غافلون.٢ وزاد: ولكن تفسحوا وتوسعوا، وكذا رواه أبو نعيم ج ٧/١٣٧.٣ قلت: هذا الحديث بهذا التمام لم أره عند [ن]، ولا عند غيره من أصحاب الستة وغيرهم، فلعله في [الكبرى] له. لكن لم يعزه إليه الحافظ المزي في [مسند جابر] من [التحفة] ولم يطبع من [الكبرى] سوى كتاب [الطهارة] وليس الحديث فيه، وإنما روى منه في [الصغرى]- كتاب اللباس ٢/٣٠٠ - النهي عن الاشتمال والاختباء، لكن ليس فيه [ليس على فرجه منه شيء]، وإنما روي هذا من حديث أبي سعيد. ورواه مسلم ٦/١٥٤ من حديث جابر، وفيه النهي عن المشي في نعل واحدة، وسيأتي بلفظ: [لا تمش. ...]، وهذا في حديث أبي هريرة أيضا عند الشيخين، وسيأتي بلفظ: [لا يمش.. ...] .وأما النهي عن المس، فلم أره عن جابر، وإنما عن ابي قتادة [، من رواية الستة، وهو مخرج في] صحيح أبي داود\" ٢٣، وقد مضى برقم ٤١٠ والله أعلم."],[7438,"«نهى أن يمشي الرجل في نعل واحدة أو خف واحدة» .\n(صحيح) [حم] عن أبي سعيد. حم ٣/٤٢. م ٦/١٥٤ - جابر١."],[7439,"«نهى أن يمنع نقع البئر» .\n(صحيح) [حم] عن عائشة. الصحيحة ٢٣٨٨: هـ، حب، ك، عد."],[7440,"«نهى أن ينام الرجل على سطح ليس بمحجور عليه» .\n(صحيح) [ت] عن جابر. الصحيحة ٨٢٨."],[7441,"«نهى أن ينتعل الرجل وهو قائم» .\n(صحيح) [ت الضياء] عن أنس. الصحيحة ٧١٩."],[7442,"«نهى أن ينفخ في الشراب وأن يشرب من ثلمة القدح أو أذنه٢» .\n(حسن) [طب] عن سهل بن سعد. الصحيحة ٣٨٨."],[7443,"«نهى أن ينفخ في الطعام والشراب، ... ...» .\n(حسن) [طب] عن ابن عباس. الضعيفة ٤٧١٥: حم."],[7444,"«نهى عن اختناث٣ الأسقية» .\n(صحيح) [حم ق د ت هـ] عن أبي سعيد. مختصر مسلم ١٢٨٧."],[7445,"(١) قلت: ومضى لفظه برقم ٤٠٥.٢ ليس في الحديث [أو أذنه] على ما في [المجمع] وإنما هو فيه من رواية ابن عباس وابن عمر قالا: [يكره أن يشرب من ثلمة القدح وأذن القدح]، وقال [رواه الطبراني ورجاله رجال الصحيح] .قلت: وبه يتقوى الحديث، وهو بدونها صحيح، لأن له شاهدا سيأتي من حديث أبي سعيد: [نهى عن الشرب.. ...] .٣ أي تكسر أفواه القرب ويشرب منها."],[7446,"«نهى عن أكل البصل» .\n(صحيح) [طب] عن أبي الدرداء. م ٢/٧٩ - ٨٠ - جابر."],[7447,"«نهى عن أكل البصل والكراث والثوم» .\n(صحيح) [الطيالسي] عن أبي سعيد. الصحيحة ٢٣٨٩."],[7448,"«نهى عن أكل الثوم» .\n(صحيح) [خ] عن ابن عمر."],[7449,"«نهى عن أكل الجلالة١ وألبانها؟» .\n(صحيح) [د ت هـ ك] عن ابن عمر. الإرواء ٢٥٠٣."],[7450,"«نهى عن أكل الضب» .\n(حسن) [ابن عساكر] عن عائشة [د] عن عبد الرحمن بن شبل. الصحيحة ٢٣٩٠."],[7451,"«نهى عن أكل المجثمة» - وهي التي تصبر بالنبل -.\n(صحيح) [ت] عن أبي الدرداء. الصحيحة ٢٣٩١: هق - ابن عباس. عق - سمرة."],[7452,"«نهى عن أكل كل ذي ناب من السباع» .\n(صحيح) [ق ٤] عن أبي ثعلبة. الإرواء ٢٤٨٥."],[7453,"«نهى عن أكل كل ذي ناب من السباع وعن أكل ذي مخلب من الطير» .\n(صحيح) [حم م د ن] عن ابن عباس. مختصر مسلم ١٣٣٢، الإرواء ٢٤٨٥."],[7454,"«نهى عن أكل لحوم الحمر الأهلية» .\n(صحيح) [ق] عن البراء وجابر وعلي وابن عمر وأبي ثعلبة. الصحيحة ٣٥٨، مختصر مسلم ٨١١، الإرواء عن ابن عمرو ٢٥٠٣."],[7455,"(١) هي التي تأكل الجلة أي العذرة من الأنعام ... [فيض القدير] ."],[7456,"«نهى عن الاختصار في الصلاة» ... [حم د ت] عن أبي هريرة.\n(صحيح) الروض النضير ١١٥٢، صحيح أبي داود ٨٧٣، الإرواء ٣٧٤ - ق."],[7457,"«نهى عن الإخصاء» .\n(صحيح) [ابن عساكر] عن ابن عمر. غاية المرام ٤٨٢."],[7458,"«نهى عن الإقران إلا أن يستأذن الرجل أخاه» .\n(صحيح) [حم ق د] عن ابن عمر."],[7459,"«نهى عن الإقعاء في الصلاة» .\n(صحيح) [ك هق] عن سمرة. الصحيحة ١٦٧٠: حم - أنس."],[7460,"«نهى عن الإقعاء١ والتورك في الصلاة» .\n(صحيح) [حم هق] عن أنس. الصحيحة: ١٦٧٠ السراج."],[7461,"«نهى عن الأكل والشرب في إناء الذهب والفضة» .\n(صحيح) [ن] عن أنس. ق - حذيفة٢."],[7462,"«نهى عن التبتل» .\n(صحيح) [حم ق د] عن سعد [حم ت ن هـ] عن سمرة."],[7463,"«نهى عن التبقر في المال» .\n(حسن) [حم] عن ابن مسعود. الصحيحة ١٢."],[7464,"«نهى عن التختم بالذهب» .\n(صحيح) [ت] عن عمران بن حصين. حم ٤/٢٨٤، ٢٨٧، ٢٩٩، ق: لباس - البراء."],[7465,"«نهى عن الترجل إلا غبا» .\n(صحيح) [حم ٣] عن عبد الله بن مغفل. الصحيحة ٥٠١."],[7466,"(١) قلت: يعني كإقعاء الكلب كما في بعض الطرق، وأما التورك فهو في غير التشهد الأخير فإنه سنة فيه.٢ يأتي حديثه بلفظ: [لا تشربوا في آنية.. ...] برقم ٧٣٣٥."],[7467,"«نهى عن التكلف للضيف» .\n(صحيح) [ك] عن سلمان. الصحيحة ٢٣٩٢: عد."],[7468,"«نهى عن الجداد بالليل والحصاد بالليل» .\n(صحيح) [هق] عن الحسين. الصحيحة ٢٣٩٣: ابن الأعرابي، خط."],[7469,"«نهى عن الجدال في القرآن» .\n(حسن) [السجزي] عن أبي سعيد. الصحيحة ٢٤١٩: الطيالسي - ابن عمرو."],[7470,"«نهى عن الجلوس على مائدة يشرب عليها الخمر وأن يأكل الرجل وهو منبطح على بطنه» .\n(حسن) [د هـ ك] عن ابن عمر. الصحيحة ٣٣٩٤."],[7471,"«نهى عن الجلالة أن يركب عليها أو يشرب من ألبانها» .\n(صحيح) [د ك] عن ابن عمر. الإرواء ٢٥٠٣، ٢٥٠٤."],[7472,"«نهى عن الحبوة يوم الجمعة والإمام يخطب» .\n(حسن) [حم د ت ك] عن معاذ بن أنس. المشكاة ١٢٩٣، صحيح أبي داود ١٠١٧."],[7473,"«نهى عن الخذف وقال: إنها لا تقتل الصيد ولا تنكي العدو ولكنها تفقأ العين وتكسر السن» ١.\n(صحيح) [حم ق د هـ] عن عبد الله بن مغفل. الروض النضير ٦٥٥."],[7474,"«نهى عن الدواء الخبيث» .\n(صحيح) [حم د ت هـ ك] عن أبي هريرة. المشكاة ٤٥٣٩."],[7475,"«نهى عن الديباج والحرير والإستبرق» .\n(صحيح) [هـ] عن البراء. حم ٤/٢٨٤و ٢٨٧، ٢٩٩، ق: لباس."],[7476,"(١) زيادة من [ق] ."],[7477,"«نهى عن الرقى والتمائم والتولة» .\n(صحيح) [ك] عن ابن مسعود. يشهد له الحديث ١٦٣٢."],[7478,"«نهى عن الركوب على جلود النمار» .\n(صحيح) [د ن] عن معاوية. الضعيفة ٤٧: حم، الطحاوي."],[7479,"«نهى عن الزور» .\n(صحيح) [ن] عن معاوية. غاية المرام ١٠٠: ق."],[7480,"«نهى عن السدل في الصلاة وأن يغطي الرجل فاه» .\n(حسن) [حم ٤ ك] عن أبي هريرة. المشكاة ٧٦٤، صحيح أبي داود ٦٥٠."],[7481,"«نهى...... عن ذبح ذوات الدر» .\n(صحيح) [هـ ك عن علي] . الضعيفة ٤٧١٩."],[7482,"«نهى عن الشراء والبيع في المسجد وأن تنشد فيه ضالة وأن ينشد فيه شعر ونهى عن التحلق قبل الصلاة يوم الجمعة» .\n(حسن) [حم ٤] عن ابن عمرو. صحيح أبي داود ٦٥٠."],[7483,"«نهى عن الشرب في آنية الذهب والفضة ونهى عن لبس الذهب والحرير ونهى عن جلود النمور أن يركب عليها» .\n(صحيح) [طب] عن معاوية. الضعيفة ٤٧."],[7484,"«نهى عن الشرب قائما ... ...» .\n(صحيح) [الضياء] عن أنس. الصحيحة ١٧٧."],[7485,"«نهى عن الشرب من ثلمة القدح وأن ينفخ في الشراب» .\n(صحيح) [حم د ك] عن أبي سعيد. الصحيحة ٣٨٧: حب، عم."],[7486,"«نهى عن الشرب من في السقاء» .\n(صحيح) [د ت هـ] عن ابن عباس. الصحيحة ٣٩٩: حم، خ، الدارمي."],[7487,"«نهى عن الشرب من في السقاء وعن ركوب الجلالة والمجثمة» ... [حم ٣ ك] عن ابن عباس.\n(صحيح) الصحيحة ٢٣٩١: الدارمي، ابن خزيمة، حب، هق."],[7488,"«نهى عن الشغار» .\n(صحيح) [حم ق ٤] عن ابن عمر. مختصر مسلم ٨٠٨، الروض النضير ٢/٥١٥."],[7489,"«نهى عن الصلاة بعد الصبح حتى تطلع الشمس وبعد العصر حتى تغرب١» .\n(صحيح) [ق ن] عن عمر."],[7490,"«نهى عن الصلاة إلى٢ القبور» .\n(صحيح) [حب] عن أنس. م - أبي مرثد٣."],[7491,"«نهى عن الصماء والاحتباء في ثوب واحد» .\n(صحيح) [د] عن جابر. حم ٣/٢٩٣و ٢٩٧و ٣٢٢و ٣٢٧و ٣٣١و ٣٤٤و ٣٤٩، م ٦/١٥٤."],[7492,"«نهى عن الصورة» .\n(صحيح) [ت٤] عن جابر. الصحيحة ٤٢٥: حم، حب."],[7493,"«نهى عن الضحك من الضرطة» ... [طس] عن جابر.\n(صحيح) حم ٤/١٧، أدب، م: جنة، ت: تفسير عبد الله بن زمعة."],[7494,"(١) فائدة هامة: اعلم أن هذا الحديث مقيد بحديث علي: [إلا أن تكون الشمس بيضاء مرتفعة] . أخرجه ابن خزيمة وغيره، وهو مخرج في [الصحيحة] ٢٠٠ وترجم له ابن خزيمة بقوله: [... إنما نهى عن الصلاة بعد العصر ... إذا كانت الشمس غير مرتفعة قد آذنت للغروب] .٢ الأصل: على، والتصحيح من [الجامع] و[حب] رقم ٣٤٣.٣ قلت: وسيأتي بلفظ: [لا تجلسوا على.. ...]، وله شاهد آخر بلفظ: [لا تصلوا إلى ... ...] .٤ في الأصل: [ن] وكذلك في بعض نسخ الجامع الصغير، وفي أخرى ما أثبتناه وهو الصواب."],[7495,"«نهى عن الكي» .\n(صحيح) [طب] عن سعد الظفري [ت ك] عن عمران. الصحيحة ١١٥٤: حم، خ، هـ، طب - ابن عباس١."],[7496,"«نهى عن المتعة٢» .\n(صحيح) [حم] عن جابر [خ] عن علي٣. الصحيحة ٣٨١."],[7497,"«نهى عن المثلة» .\n(صحيح) [ك] عن عمران [طب] عن ابن عمر وعن المغيرة. الإرواء ٢٢٣٠."],[7498,"«نهى عن المحاقلة والمخاصرة والملامسة والمنابذة والمزابنة» .\n(صحيح) [خ] عن أنس. الإرواء ١٣٥٣، الروض النضير ٢/٥١٥، أحاديث البيوع."],[7499,"«نهى عن المخابرة» .\n(صحيح) [حم] عن زيد بن ثابت. الإرواء ١٤٧٨، أحاديث البيوع."],[7500,"«نهى عن المزابنة» .\n(صحيح) [ق ن هـ] عن ابن عمر. مختصر مسلم ٩١٢، أحاديث البيوع: مالك، الشافعي، حم، ت، الطحاوي، هق."],[7501,"«نهى عن المزابنة والمحاقلة» .\n(صحيح) [ق] عن أبي سعيد. غاية المرام ٣٦٩، أحاديث البيوع."],[7502,"«نهى عن المزارعة» ... [حم م] عن ثابت بن الضحاك.\n(صحيح) مختصر مسلم ٩٧٥، غاية المرام ٣٥٥، أحاديث البيوع."],[7503,"(١) قلت: وقد مضى حديثه برقم ٣٧٣٤.٢ يعني متعة النكاح، وأما متعة الحج، فقد أمر بها النبي صلى الله عليه وآله وسلم وجعلها شريعة مستمرة إلى يوم القيامة، راجع [حجة النبي صلى الله عليه وآله وسلم] والحديث الآتي برقم ٧٠١٣.٣ قلت: و[م] عن سبرة بن معبد، وزاد: إلا أنها حرام إلى يوم القيامة."],[7504,"«نهى عن المفدم» ١.\n(صحيح) [هـ] عن ابن عمر. الصحيحة ٢٣٩٥: ق، حم - علي."],[7505,"«نهى عن المنابذة وعن الملامسة» .\n(صحيح) [حم ق د ن هـ] عن أبي سعيد. أحاديث البيوع. الشافعي، الدارمي، ابن الجارود، هق."],[7506,"«نهى عن المياثر الحمر والقسي» .\n(صحيح) [خ ت] عن البراء. المشكاة ٤٣٥٨."],[7507,"«نهى عن الميثرة الأرجوان» .\n(صحيح) [ت] عن عمران. الصحيحة ٢٣٩٦: حم، د، ق - علي."],[7508,"«نهى عن النجش» ... [ق ن هـ] عن ابن عمر.\n(صحيح) الإرواء ١٣١٨، غاية المرام ٣٣٥، أحاديث البيوع، مختصر مسلم ٩٤٠."],[7509,"«نهى عن النذر» ز\n(صحيح) [ق د ن هـ] عن ابن عمر. مختصر مسلم ١٠٠٦، الإرواء ٢٥٨٥."],[7510,"«نهى عن النعي» .\n(حسن) [حم ت هـ] عن حذيفة. أحكام الجنائز ص ٣٠ - ٣١: ابن أبي شيبة، هق."],[7511,"«نهى عن النفخ في الشراب» .\n(صحيح) [ت] عن أبي سعيد. الصحيحة ٣٨٥."],[7512,"«نهى عن النفخ في الطعام والشراب» .\n(صحيح) [حم] عن ابن عباس. الإرواء ١٩٧٧، الضعيفة ٤٧١٥."],[7513,"\"نهى عن النوح ... والتصاوير وجلود السباع، والتبرج والغناء والذهب والخز والحرير\".\n(صحيح) [حم] عن معاوية. الضعيفة ٤٧٢٥."],[7514,"(١) هو الثوب المشبع حمرة بالعصفر، كأنه الذي لا يقدر على الزيادة عليه لتناهي حمرته، فهو كالممتنع من قبول الصبغ كما في [الفيض] ."],[7515,"«نهى عن النوم قبل العشاء وعن الحديث بعدها» .\n(صحيح) [طب] عن ابن عباس. الروض النضير ٩١٥: طص - أبي برزة."],[7516,"«نهى عن النياحة» .\n(صحيح) [د] عن أم عطية. أحكام الجنائز ٤٨: ق."],[7517,"«نهى عن النهبى والمثلة» .\n(صحيح) [حم خ] عن عبد الله بن زيد. الإرواء ١٩٥٩."],[7518,"«نهى عن النهبة والخلسة» ١.\n(صحيح) [حم] عن زيد بن خالد. الصحيحة ١٦٧٣."],[7519,"«نهى عن الوحدة: أن يبيت الرجل وحده» .\n(صحيح) [حم] عن ابن عمر. الصحيحة ٦٠."],[7520,"«نهى عن الوسم في الوجه والضرب في الوجه» .\n(صحيح) [حم م ت] عن جابر. الإرواء ٢١٨٥."],[7521,"«نهى عن الوشم» .\n(صحيح) [حم] عن أبي هريرة. غاية المرام ٩٧."],[7522,"«نهى عن الوصال» .\n(صحيح) [ق] عن ابن عمر وأبي هريرة وعائشة. مختصر مسلم ٥٩٥، غاية المرام ٩٣، ٩٥، ٩٧، ٩٨."],[7523,"«نهى عن بيع الثمار حتى تنجو من العاهة» .\n(صحيح) [طب] عن زيد بن ثابت. أحاديث البيوع: حم، خ، د، الطحاوي، ع، قط، هق."],[7524,"(١) بالضم ما يؤخذ سلبا ومكابرة، ووقع في الأصل: [الخليسة] تبعا لـ[الجامع] وعليه شرحه المناوي، وهو خطأ كما بينته في المصدر المذكور أعلاه."],[7525,"«نهى عن بيع الثمار حتى يبدو صلاحها وتأمن العاهة» .\n(صحيح) [حم] عن عائشة. أحاديث البيوع: الطحاوي."],[7526,"«نهى عن بيع الثمر بالتمر» .\n(صحيح) [ق د] عن سهل بن أبي حثمة. أحاديث البيوع: الشافعي، حم، ن، الطحاوي، هق."],[7527,"«نهى عن بيع الثمر بالتمر كيلا وعن بيع العنب بالزبيب كيلا وعن بيع الزرع بالحنطة كيلا» .\n(صحيح) [د] عن ابن عمر. أحاديث البيوع: الطحاوي، هق."],[7528,"«نهى عن بيع الثمر حتى يطيب» .\n(صحيح) [حم ق] عن جابر. مختصر مسلم ٩١٥، أحاديث البيوع."],[7529,"«نهى عن بيع الثمرة حتى يبدو صلاحها وعن النخل حتى تزهو» ... [خ] عن أنس.\n(صحيح) الإرواء ١٣٦٥، أحاديث البيوع: مالك، الشافعي، حم، م، ن."],[7530,"«نهى عن بيع الحصاة وعن بيع الغرر» .\n(صحيح) [م ٤] عن أبي هريرة. مختصر مسلم ٣٩، الإرواء ١٢٩٤."],[7531,"«نهى عن بيع الحيوان بالحيوان نسيئة» .\n(صحيح) [حم ٤ الضياء] عن سمرة. المشكاة ٢٨٢٢، أحاديث البيوع: الدارمي، الطحاوي، ابن الجارود، هق."],[7532,"«نهى عن بيع الذهب بالورق دينا» .\n(صحيح) [حم ق ن] عن البراء وزيد بن أرقم. أحاديث البيوع: الطيالسي، هق."],[7533,"«نهى عن بيع السنين» ... [حم م د ن هـ] عن جابر.\n(صحيح) أحاديث البيوع: الشافعي، الطحاوي، ابن الجارود. الطحاوي، طب - سمرة. مختصر مسلم ٩٢٦."],[7534,"«نهى عن بيع الشاة باللحم» .\n(حسن) [ك هق] عن سمرة. الإرواء ١٣٥٠، أحاديث البيوع."],[7535,"«نهى عن بيع الصبرة من التمر لا يعلم مكيلها بالكيل المسمى من التمر» ... [حم م ن] عن جابر.\n(صحيح) مختصر مسلم ٩١٤، أحاديث البيوع: الشافعي، ابن الجارود، ك، هق."],[7536,"«نهى عن بيع الطعام حتى يجري فيه الصاعان فيكون لصاحبه الزيادة وعليه النقصان» .\n(حسن) [البزار] عن أبي هريرة. أحاديث البيوع: هق."],[7537,"«نهى عن بيع اللحم بالحيوان» .\n(حسن) [مالك الشافعي ك] عن سعيد بن المسيب مرسلا [البزار] عن ابن عمر. المشكاة ٢٨٢١، الإرواء ١٣٥١."],[7538,"«نهى عن بيع المضامين والملاقح وحبل الحبلة» .\n(صحيح) [طب] عن ابن عباس. أحاديث البيوع: طب. البزار - أبي هريرة. عب - ابن عمر."],[7539,"«نهى عن بيع النخل حتى يزهو وعن السنبل حتى يبيض ويأمن العاهة» ... [م د ت] عن ابن عمر.\n(صحيح) مختصر مسلم ٩١٧، أحاديث البيوع: حم. ابن الجارود، هق."],[7540,"«نهى عن بيع الولاء وعن هبته» .\n(صحيح) [حم ق ٤] عن ابن عمر. مختصر مسلم ٨٩٨، أحاديث البيوع: الدارمي، هق."],[7541,"\"نهى عن بيع حبل الحبلة.\n(صحيح) [حم ق ٤] عن ابن عمر. أحاديث البيوع: مالك، الشافعي، هق."],[7542,"«نهى عن بيع ضراب الجمل وعن بيع الماء والأرض لتحرث» .\n(صحيح) [حم م ن] عن جابر. أحاديث البيوع: هق."],[7543,"«نهى عن بيع فضل الماء» .\n(صحيح) [م ن هـ] عن جابر [حم ٤] عن إياس بن عبيد\". مختصر مسلم ٩٧٩. أحاديث البيوع: الدارمي، ك، هق - إياس."],[7544,"«نهى عن بيعتين في بيعة» ... [ت ن] عن أبي هريرة.\n(صحيح) المشكاة ٢٨٦٨، الإرواء ١٣٠٧، أحاديث البيوع: البزار - ابن عمر."],[7545,"«نهى عن تلقي البيوع» .\n(صحيح) [ت] عن ابن مسعود. غاية المرام: ٣٣٦، أحاديث البيوع: م."],[7546,"«نهى عن تلقي الجلب» .\n(صحيح) [هـ] عن ابن عمر. غاية المرام ٣٣٦، أحاديث البيوع."],[7547,"«نهى عن ثمن الكلب إلا كلب الصيد» .\n(حسن) [ت] عن أبي هريرة. التعليق على الروضة الندية ٢/٩٤: هق."],[7548,"«نهى عن ثمن الكلب إلا الكلب المعلم» .\n(حسن) [حم ن] عن جابر. المصدر نفسه: هق."],[7549,"«نهى عن ثمن الكلب وثمن الخنزير وثمن الخمر وعن مهر البغي وعن عسب الفحل» .\n(صحيح) [طس] عن ابن عمرو. أحاديث البيوع."],[7550,"«نهى عن ثمن الكلب وثمن الدم وكسب البغي» .\n(صحيح) [خ] عن أبي جحيفة. أحاديث البيوع: الطيالسي، حم، هق."],[7551,"«نهى عن ثمن الكلب وعن ثمن السنور» .\n(صحيح) [حم ٤ ك] عن جابر. أحاديث البيوع: م، الطحاوي، قط."],[7552,"«نهى عن ثمن الكلب ومهر البغي وحلوان الكاهن» .\n(صحيح) [ق ٤] عن أبي مسعود. مختصر مسلم ٩٣٢، الإرواء ١٢٩١، ١٣٢٥، أحاديث البيوع: الشافعي، أحمد، الطحاوي، ابن الجارود."],[7553,"«نهى عن جلد الحد في المساجد» .\n(صحيح) [هـ] عن ابن عمرو. الإرواء ٢٢١٤، ٢٣٢٧."],[7554,"«نهى عن جلود السباع» .\n(صحيح) [ك] عن والد أبي مليح. المشكاة ٥٠٦، الأحاديث الصحيحة ١٠١١."],[7555,"«نهى عن خاتم الذهب» .\n(صحيح) [م] عن أبي هريرة."],[7556,"«نهى عن خاتم الذهب وعن خاتم الحديد» .\n(صحيح) [هب] عن ابن عمرو. الصحيحة ١٢٤١."],[7557,"«نهى عن خصاء الخيل والبهائم» .\n(صحيح) [حم] عن ابن عمر. غاية المرام ٤٨٢."],[7558,"«نهى عن ركوب النمور» .\n(صحيح) [هـ] عن أبي ريحانة. المشكاة ٤٣٩٥."],[7559,"«نهى عن سب الأموات» .\n(صحيح) [ك] عن زيد بن أرقم. الصحيحة ٢٣٩٧: حم، حل - عائشة."],[7560,"«نهى عن سلف وبيع وشرطين في بيع وبيع ما ليس عندك وربح ما لم تضمن» .\n(صحيح) [طب] عن حكيم بن حزام. أحاديث البيوع: ٤ - ابن عمرو١."],[7561,"«نهى عن صبر الروح وخصاء البهائم» .\n(صحيح) [هق] عن ابن عباس. غاية المرام ٤٨٢: البزار."],[7562,"«نهى عن صوم ستة أيام من السنة: ثلاثة أيام التشريق ويوم الفطر ويوم الأضحى ويوم الجمعة مختصة من الأيام» .\n(صحيح) [الطيالسي] عن أنس. الصحيحة ٢٣٩٨."],[7563,"«نهى عن صوم يوم الفطر والنحر» .\n(صحيح) [ق] عن عمر وأبي سعيد. الإرواء ٩٦٢."],[7564,"«نهى عن صيام يوم الجمعة» .\n(صحيح) [حم ق هـ] عن جابر. الصحيحة ١٠١٢."],[7565,"«نهى عن صيام يوم قبل رمضان والأضحى والفطر وأيام التشريق» .\n(صحيح) [هق] عن أبي هريرة. الصحيحة ٢٣٩٨."],[7566,"«نهى عن طعام المتباريين أن يؤكل» .\n(صحيح) [د ك] عن ابن عباس. الصحيحة ٦٢٧."],[7567,"«نهى عن عسب الفحل» .\n(صحيح) [حم خ ٣] عن ابن عمر."],[7568,"«نهى عن عسب الفحل وقفيز الطحان» .\n(صحيح) [قط] عن أبي سعيد. الإرواء ١٤٧٦، أحاديث البيوع: ع، الطحاوي، هق."],[7569,"(١) قلت: وسيأتي حديثه بلفظ: [لا يحل سلف وبيع.. ...] و[شرطين في بيع] وهو بيع التقسيط، كما سيأتي بيانه هناك."],[7570,"«نهى عن قتل أربع من الدواب: النملة والنحلة والهدهد والصرد» ... [حم د هـ] عن ابن عباس.\n(صحيح) الإرواء ٢٤٩٠، الدارمي: الطحاوي، حب، هق."],[7571,"«نهى عن قتل الصبر» .\n(صحيح) [د] عن أبي أيوب. حب ١٦٦٠. حم، م - جابر١."],[7572,"«نهى عن قتل: الصرد والضفدع والنملة والهدهد» .\n(صحيح) [هـ] عن أبي هريرة. الإرواء ٢٤٩٠."],[7573,"«نهى عن قتل الضفدع للدواء» .\n(صحيح) [حم د ن ك] عن عبد الرحمن بن عثمان التيمي. الروض النضير ١/٢٦٥."],[7574,"«نهى عن قتل النساء والصبيان» .\n(صحيح) [ق] عن ابن عمر. الإرواء ١٢١٠، المشكاة ٤٥٤٥."],[7575,"«نهى عن قتل كل ذي روح.. ...» .\n(صحيح) [طب] عن ابن عباس. الضعيفة ٤٧٣٠."],[7576,"«نهى عن كسب الإماء» ... [خ د] عن أبي هريرة.\n(صحيح) أحاديث البيوع: الطيالسي، الطحاوي، منتقى ابن الجارود."],[7577,"«نهى عن كسب الأمة حتى يعلم من أين هو» .\n(حسن) [د ك] عن رافع بن خديج. أحاديث البيوع."],[7578,"«نهى عن كسب الحجام» .\n(صحيح) [هـ] عن أبي مسعود. أحاديث البيوع."],[7579,"«نهى عن كل مسكر ... ...» .\n(صحيح) [حم د] عن أم سلمة. الضعيفة ٤٧٣٢."],[7580,"(١) قلت: ومضى حديثه قريبا برقم ٦٨٣٩."],[7581,"«نهى عن لبن الجلالة» .\n(صحيح) [د ك] عن ابن عباس. الصحيحة ٢٣٩١: حب."],[7582,"«نهى عن لقطة الحاج» .\n(صحيح) [حم م د] عن عبد الرحمن بن عثمان التيمي. مختصر مسلم ١٠٦١."],[7583,"«نهى عن محاش النساء» .\n(صحيح) [طس] عن جابر. الصحيحة ٢٣٩٩: عد، عقبة بن عامر."],[7584,"«نهى عن نتف الشيب» .\n(صحيح) [ت ن هـ] عن ابن عمرو. المشكاة ٤٤٥٨."],[7585,"«نهى عن نقرة الغراب وافتراش السبع وأن يوطن الرجل المكان في المسجد كما يوطن البعير» .\n(حسن) [حم د ن هـ ك] عن عبد الرحمن بن شبل. المشكاة ٩٠٣، صحيح أبي داود ٨٠٨، الصحيحة ١١٦٨."],[7586,"حرف الهاء"],[7587,"٢٣٢٣ - «هذا ابن آدم وهذا أجله وثم أمله وثم أمله وثم أمله» .\n(صحيح) [حم ت ن هـ حب] عن أنس. المشكاة ٥٢٧٧."],[7588,"٢٣٢٤ - «هذا الأمل وهذا أجله فبينما هوكذلك إذ جاءه الخط الأقرب» .\n(صحيح) [خ ت] عن أنس. المشكاة ٥٢٧٧."],[7589,"«هذا الإنسان وهذا أجله محيط به وهذا الذي هوخارج أمله وهذه الخطوط الصغار الأعراض فإن أخطأ هذا نهشه هذا وإن أخطأ هذا نهشه هذا» .\n(صحيح) [حم خ ت هـ] عن ابن مسعود."],[7590,"«هذا القرع نكثر به طعامنا» .\n(صحيح) [حم ن هـ] عن جابر بن طارق. الصحيحة ٢٤٠٠: ت في [الشمائل] ."],[7591,"٢٣٢٦ - «هذا الذي تحرك له العرش وفتحت له أبواب السماء وشهده سبعون ألفا من الملائكة لقد ضم ضمة ثم فرج عنه» .\n(صحيح) [ن] عن ابن عمر. الصحيحة ١٦٩٥: ابن سعد."]])